function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.min(sceneCount - 1, Math.floor(loopT / sceneDuration));
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const subP = (p, a, b) => clamp01((p - a) / (b - a));
  const easeInOutCubic = (x) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2);
  const easeOutCubic = (x) => 1 - Math.pow(1 - x, 3);
  const easeInCubic = (x) => x * x * x;

  ctx.save();
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  // 1. Clean Modern Dark Aesthetic Gradient Background (Zero glow effects)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, '#140A10');
  bgGrad.addColorStop(0.52, '#24141D');
  bgGrad.addColorStop(1, '#090508');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Timeline Choreography Parameters
  let plinthScale = 0.22;
  let houseReveal = 0;
  let roofReveal = 0;
  let chimneyReveal = 0;
  let icingTrim = 0;
  let candyPop = 0;
  let candyRot = 0;
  let windowWarmth = 0;
  let smokeAlpha = 0;
  let snowFlankAlpha = 0;

  if (currentScene === 0) {
    // Scene 1: Sugar snow plinth, gingerbread walls & door, pitched frosted roof, scalloped icing trim-path
    plinthScale = 0.22 + 0.78 * easeOutCubic(subP(sceneProgress, 0.0, 0.18));
    houseReveal = easeOutCubic(subP(sceneProgress, 0.12, 0.42));
    roofReveal = easeOutCubic(subP(sceneProgress, 0.32, 0.60));
    chimneyReveal = easeOutCubic(subP(sceneProgress, 0.46, 0.72));
    icingTrim = easeInOutCubic(subP(sceneProgress, 0.52, 0.94));
  } else if (currentScene === 1) {
    // Scene 2: Synchronized spinning peppermint candies, warm hearth windows, S-curve chimney smoke
    plinthScale = 1;
    houseReveal = 1;
    roofReveal = 1;
    chimneyReveal = 1;
    icingTrim = 1;

    candyPop = easeOutCubic(subP(sceneProgress, 0.02, 0.28));
    candyRot = easeInOutCubic(sceneProgress) * Math.PI * 2;
    windowWarmth = easeInOutCubic(subP(sceneProgress, 0.08, 0.38));
    smokeAlpha = easeInOutCubic(subP(sceneProgress, 0.16, 0.42));
    snowFlankAlpha = easeInOutCubic(subP(sceneProgress, 0.14, 0.40));
  } else {
    // Scene 3: Smoke fades, windows dim, candies retract, icing untrims, house folds seamlessly to plinth
    snowFlankAlpha = 1 - easeInOutCubic(subP(sceneProgress, 0.0, 0.30));
    smokeAlpha = 1 - easeInOutCubic(subP(sceneProgress, 0.0, 0.34));
    windowWarmth = 1 - easeInOutCubic(subP(sceneProgress, 0.10, 0.42));
    candyPop = 1 - easeInCubic(subP(sceneProgress, 0.20, 0.50));
    candyRot = Math.PI * 2 + easeOutCubic(subP(sceneProgress, 0.0, 0.48)) * (Math.PI * 0.5);

    icingTrim = 1 - easeInOutCubic(subP(sceneProgress, 0.40, 0.68));
    chimneyReveal = 1 - easeInCubic(subP(sceneProgress, 0.50, 0.72));
    roofReveal = 1 - easeInCubic(subP(sceneProgress, 0.56, 0.80));
    houseReveal = 1 - easeInCubic(subP(sceneProgress, 0.64, 0.88));
    plinthScale = 1 - 0.78 * easeInOutCubic(subP(sceneProgress, 0.80, 1.0));
  }

  // 3. Geometric Layout Constants (Strict clearance between door, windows, candies & roof)
  const baseBotY = cy + minSide * 0.275;
  const plinthH = minSide * 0.022;
  const plinthW = minSide * 0.390;
  const wallBotY = baseBotY - plinthH * 0.85;
  const houseW = minSide * 0.295;
  const wallTopY = cy + minSide * 0.015;
  const peakY = cy - minSide * 0.175;
  const eaveY = wallTopY + minSide * 0.024;
  const roofHalfW = minSide * 0.194;

  // Helper: Draw 6-Wedge Spinning Peppermint Candy Pinwheel
  function drawPeppermint(px, py, rad, rot, primaryCol, scale) {
    if (scale <= 0.01 || rad <= 0.4) return;
    ctx.save();
    ctx.translate(px, py);
    ctx.scale(scale, scale);
    ctx.rotate(rot);

    ctx.beginPath();
    ctx.arc(0, 0, rad, 0, Math.PI * 2);
    ctx.fillStyle = '#FFF8F2';
    ctx.fill();

    ctx.save();
    ctx.clip();
    const wedges = 6;
    const step = (Math.PI * 2) / wedges;
    for (let w = 0; w < wedges; w += 2) {
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.arc(0, 0, rad * 1.1, w * step, (w + 1) * step);
      ctx.closePath();
      ctx.fillStyle = primaryCol;
      ctx.fill();
    }
    ctx.restore();

    // Crisp outer rim ring & center sugar button
    ctx.beginPath();
    ctx.arc(0, 0, rad, 0, Math.PI * 2);
    ctx.strokeStyle = '#6E391B';
    ctx.lineWidth = Math.max(1.5, rad * 0.12);
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(0, 0, rad * 0.22, 0, Math.PI * 2);
    ctx.fillStyle = '#FFF8F2';
    ctx.fill();

    ctx.restore();
  }

  // Helper: Draw 4-Point Sugar Spark
  function drawSpark(sx, sy, sz, rot, col, alpha) {
    if (sz <= 0.4 || alpha <= 0.01) return;
    ctx.save();
    ctx.translate(sx, sy);
    ctx.rotate(rot);
    ctx.globalAlpha = alpha;
    ctx.beginPath();
    const inner = sz * 0.30;
    for (let i = 0; i < 8; i++) {
      const a = (i * Math.PI) / 4;
      const r = i % 2 === 0 ? sz : inner;
      if (i === 0) ctx.moveTo(Math.cos(a) * r, Math.sin(a) * r);
      else ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r);
    }
    ctx.closePath();
    ctx.fillStyle = col;
    ctx.fill();
    ctx.restore();
  }

  // 4. Exterior Flanking Sugar-Snow Sparks & Falling Dots (Strictly outside house silhouette)
  if (snowFlankAlpha > 0.005) {
    const flanks = [
      { x: cx - minSide * 0.30, y: cy - minSide * 0.08, sz: minSide * 0.015, col: '#38D9B5' },
      { x: cx - minSide * 0.32, y: cy + minSide * 0.12, sz: minSide * 0.012, col: '#FF5D8F' },
      { x: cx + minSide * 0.30, y: cy - minSide * 0.08, sz: minSide * 0.015, col: '#FFD166' },
      { x: cx + minSide * 0.32, y: cy + minSide * 0.12, sz: minSide * 0.012, col: '#38D9B5' },
    ];
    for (let i = 0; i < flanks.length; i++) {
      const fl = flanks[i];
      const pulse = 0.85 + 0.15 * Math.sin(loopT * Math.PI * 0.9 + i * 1.4);
      drawSpark(fl.x, fl.y, fl.sz * snowFlankAlpha * pulse, loopT * 0.5 + i, fl.col, snowFlankAlpha * 0.88);
    }

    // 4 gentle sugar-snow dots strictly in outer flank columns (|dx| >= 0.25 * minSide)
    const sugarDots = [
      { x: cx - minSide * 0.255, shift: 0.0, r: minSide * 0.0042 },
      { x: cx - minSide * 0.355, shift: 0.45, r: minSide * 0.0034 },
      { x: cx + minSide * 0.255, shift: 0.25, r: minSide * 0.0042 },
      { x: cx + minSide * 0.355, shift: 0.70, r: minSide * 0.0034 },
    ];
    for (let d = 0; d < sugarDots.length; d++) {
      const sd = sugarDots[d];
      const u = (loopT * 0.14 + sd.shift) % 1;
      const dy = cy - minSide * 0.22 + u * (minSide * 0.46);
      const fade = Math.sin(u * Math.PI) * snowFlankAlpha * 0.75;
      if (fade > 0.02) {
        ctx.beginPath();
        ctx.arc(sd.x, dy, sd.r, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(255, 248, 242, ${fade.toFixed(3)})`;
        ctx.fill();
      }
    }
  }

  // 5. Chimney & Rising S-Curve Smoke Clouds (Drawn behind roof overhang on right slope)
  const chimX = cx + minSide * 0.095;
  const chimW = minSide * 0.044;
  const chimTopY = peakY + minSide * 0.026;
  const chimBaseY = wallTopY + minSide * 0.01;

  if (chimneyReveal > 0.01) {
    ctx.save();
    const curChimY = chimBaseY - (chimBaseY - chimTopY) * chimneyReveal;

    // Chimney brick cookie body
    ctx.beginPath();
    ctx.roundRect(chimX - chimW * 0.5, curChimY, chimW, chimBaseY - curChimY, minSide * 0.006);
    ctx.fillStyle = '#9C5629';
    ctx.fill();

    // Thick white icing collar on chimney top
    if (chimneyReveal > 0.35) {
      const capW = chimW * 1.24;
      const capH = minSide * 0.018;
      ctx.beginPath();
      ctx.roundRect(chimX - capW * 0.5, curChimY - minSide * 0.004, capW, capH, capH * 0.45);
      ctx.fillStyle = '#FFF8F2';
      ctx.fill();
    }

    // 3 Rising Round Smoke Puffs strictly in clear corridor above chimney
    if (smokeAlpha > 0.01 && chimneyReveal > 0.85) {
      for (let s = 0; s < 3; s++) {
        const u = (loopT * 0.26 + s * 0.333) % 1;
        const pY = (curChimY - minSide * 0.024) - u * (minSide * 0.145);
        const pX = chimX + Math.sin(u * Math.PI * 1.5) * (minSide * 0.024);
        const pR = minSide * (0.010 + u * 0.014);
        const fade = Math.sin(u * Math.PI) * smokeAlpha * 0.72;
        if (fade > 0.02) {
          ctx.beginPath();
          ctx.arc(pX, pY, pR, 0, Math.PI * 2);
          ctx.fillStyle = `rgba(255, 248, 242, ${fade.toFixed(3)})`;
          ctx.fill();
        }
      }
    }

    ctx.restore();
  }

  // 6. Gingerbread House Facade Walls + Gable + Door + Windows + Peppermints
  if (houseReveal > 0.01) {
    ctx.save();
    ctx.translate(cx, wallBotY);
    ctx.scale(1, houseReveal);
    ctx.translate(-cx, -wallBotY);
    ctx.globalAlpha = clamp01(houseReveal * 1.5);

    // Main Toasted Gingerbread Facade Pentagon
    const houseGrad = ctx.createLinearGradient(cx - houseW * 0.5, peakY, cx + houseW * 0.5, wallBotY);
    houseGrad.addColorStop(0, '#D48A50');
    houseGrad.addColorStop(0.55, '#BD713B');
    houseGrad.addColorStop(1, '#965124');

    ctx.beginPath();
    ctx.moveTo(cx, peakY);
    ctx.lineTo(cx + houseW * 0.5, wallTopY);
    ctx.lineTo(cx + houseW * 0.5, wallBotY);
    ctx.lineTo(cx - houseW * 0.5, wallBotY);
    ctx.lineTo(cx - houseW * 0.5, wallTopY);
    ctx.closePath();
    ctx.fillStyle = houseGrad;
    ctx.fill();

    // Clipped interior eave shadow directly beneath roof slope
    ctx.save();
    ctx.clip();
    ctx.beginPath();
    ctx.moveTo(cx, peakY + minSide * 0.014);
    ctx.lineTo(cx + houseW * 0.52, wallTopY + minSide * 0.018);
    ctx.lineTo(cx - houseW * 0.52, wallTopY + minSide * 0.018);
    ctx.lineWidth = minSide * 0.022;
    ctx.strokeStyle = 'rgba(55, 22, 10, 0.24)';
    ctx.stroke();
    ctx.restore();

    // Central Arched Chocolate Door + Animated Piped Icing Door Arch
    const doorW = minSide * 0.070;
    const doorH = minSide * 0.122;
    const doorTop = wallBotY - doorH;
    const doorArchR = doorW * 0.5;

    ctx.beginPath();
    ctx.moveTo(cx - doorW * 0.5, wallBotY);
    ctx.lineTo(cx - doorW * 0.5, doorTop + doorArchR);
    ctx.arc(cx, doorTop + doorArchR, doorArchR, Math.PI, 0, false);
    ctx.lineTo(cx + doorW * 0.5, wallBotY);
    ctx.closePath();
    ctx.fillStyle = '#6E391B';
    ctx.fill();

    // Subtle candy knob on door right side
    ctx.beginPath();
    ctx.arc(cx + doorW * 0.24, wallBotY - doorH * 0.42, minSide * 0.006, 0, Math.PI * 2);
    ctx.fillStyle = '#FFD166';
    ctx.fill();

    // Piped Icing Door Frame (trim-path progressive reveal)
    if (icingTrim > 0.01) {
      const doorFrameLen = (doorH - doorArchR) * 2 + Math.PI * doorArchR;
      ctx.save();
      ctx.beginPath();
      ctx.moveTo(cx - doorW * 0.5, wallBotY - minSide * 0.004);
      ctx.lineTo(cx - doorW * 0.5, doorTop + doorArchR);
      ctx.arc(cx, doorTop + doorArchR, doorArchR, Math.PI, 0, false);
      ctx.lineTo(cx + doorW * 0.5, wallBotY - minSide * 0.004);
      ctx.strokeStyle = '#FFF8F2';
      ctx.lineWidth = minSide * 0.0085;
      ctx.setLineDash([doorFrameLen]);
      ctx.lineDashOffset = doorFrameLen * (1 - icingTrim);
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.restore();
    }

    // Two Symmetric Round Warm Glowing Windows (Strict separation from door & walls)
    const winXOff = minSide * 0.092;
    const winY = cy + minSide * 0.138;
    const winR = minSide * 0.024;
    for (let side = -1; side <= 1; side += 2) {
      const wx = cx + side * winXOff;
      // Outer cookie icing frame
      ctx.beginPath();
      ctx.arc(wx, winY, winR + minSide * 0.0055, 0, Math.PI * 2);
      ctx.fillStyle = '#FFF8F2';
      ctx.fill();

      // Window glass pane (dark warm -> glowing Butter Gold)
      ctx.beginPath();
      ctx.arc(wx, winY, winR, 0, Math.PI * 2);
      ctx.fillStyle = '#3B1E14';
      ctx.fill();

      if (windowWarmth > 0.02) {
        ctx.save();
        ctx.globalAlpha = windowWarmth;
        const winGrad = ctx.createRadialGradient(wx, winY, winR * 0.1, wx, winY, winR);
        winGrad.addColorStop(0, '#FFF5C4');
        winGrad.addColorStop(0.7, '#FFD166');
        winGrad.addColorStop(1, '#F29F38');
        ctx.fillStyle = winGrad;
        ctx.fill();
        ctx.restore();
      }

      // Crisp cross muntins
      ctx.strokeStyle = '#6E391B';
      ctx.lineWidth = minSide * 0.0042;
      ctx.beginPath();
      ctx.moveTo(wx - winR, winY);
      ctx.lineTo(wx + winR, winY);
      ctx.moveTo(wx, winY - winR);
      ctx.lineTo(wx, winY + winR);
      ctx.stroke();
    }

    // 3 Spinning Peppermint Candies (Strictly spaced: Gable peak + Left & Right upper shoulders)
    if (candyPop > 0.01) {
      const pPeak = easeOutCubic(subP(candyPop, 0.0, 0.65));
      const pSides = easeOutCubic(subP(candyPop, 0.25, 1.0));
      drawPeppermint(cx, cy - minSide * 0.055, minSide * 0.028, candyRot, '#FF5D8F', pPeak);
      drawPeppermint(cx - winXOff, cy + minSide * 0.068, minSide * 0.0165, -candyRot, '#38D9B5', pSides);
      drawPeppermint(cx + winXOff, cy + minSide * 0.068, minSide * 0.0165, candyRot, '#38D9B5', pSides);
    }

    ctx.restore();
  }

  // 7. Pitched Sugar-Frosted Roof Cap + Animated Scalloped Piped Icing Trim
  if (roofReveal > 0.01) {
    ctx.save();
    const dropY = -(1 - roofReveal) * (minSide * 0.055);
    ctx.translate(0, dropY);
    ctx.globalAlpha = clamp01(roofReveal * 1.4);

    // Main Thick Frosted Roof Slopes
    const roofPeak = peakY - minSide * 0.010;
    ctx.beginPath();
    ctx.moveTo(cx - roofHalfW, eaveY);
    ctx.lineTo(cx, roofPeak);
    ctx.lineTo(cx + roofHalfW, eaveY);
    ctx.strokeStyle = '#FFF8F2';
    ctx.lineWidth = minSide * 0.032;
    ctx.stroke();

    // Inner subtle creamy bevel along lower roof edge
    ctx.beginPath();
    ctx.moveTo(cx - roofHalfW + minSide * 0.004, eaveY + minSide * 0.006);
    ctx.lineTo(cx, roofPeak + minSide * 0.008);
    ctx.lineTo(cx + roofHalfW - minSide * 0.004, eaveY + minSide * 0.006);
    ctx.strokeStyle = '#E8DDD2';
    ctx.lineWidth = minSide * 0.010;
    ctx.stroke();

    // Animated Piped Scalloped Mint/Pink/White Icing Beads along both roof slopes (trim-path reveal)
    if (icingTrim > 0.01 && roofReveal > 0.7) {
      const beadCount = 5; // 5 clean scallops per slope
      for (let side = -1; side <= 1; side += 2) {
        for (let b = 0; b < beadCount; b++) {
          const u = (b + 0.5) / beadCount;
          const threshold = b / beadCount;
          const pop = easeOutCubic(subP(icingTrim, threshold * 0.7, threshold * 0.7 + 0.30));
          if (pop <= 0.01) continue;

          const bx = cx + side * (roofHalfW * 0.88) * u;
          const by = (roofPeak + minSide * 0.016) + (eaveY - roofPeak) * u;
          const col = b % 2 === 0 ? '#38D9B5' : '#FF5D8F';

          ctx.beginPath();
          ctx.arc(bx, by, minSide * 0.0075 * pop, 0, Math.PI * 2);
          ctx.fillStyle = col;
          ctx.fill();
        }
      }
    }

    ctx.restore();
  }

  // 8. Sugar Frosting Snow Plinth Base (Always poised at t=0 and t=20 for seamless anchor)
  ctx.save();
  const curPlinthW = plinthW * plinthScale;
  ctx.beginPath();
  ctx.roundRect(cx - curPlinthW * 0.5, baseBotY - plinthH, curPlinthW, plinthH, plinthH * 0.48);
  const plGrad = ctx.createLinearGradient(cx - curPlinthW * 0.5, baseBotY - plinthH, cx + curPlinthW * 0.5, baseBotY);
  plGrad.addColorStop(0, '#FFF8F2');
  plGrad.addColorStop(1, '#E2D4C6');
  ctx.fillStyle = plGrad;
  ctx.fill();
  ctx.restore();

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.min(sceneCount - 1, Math.floor(loopT / sceneDuration));
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const subP = (p, a, b) => clamp01((p - a) / (b - a));
  const easeInOutCubic = (x) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2);
  const easeOutCubic = (x) => 1 - Math.pow(1 - x, 3);
  const easeInCubic = (x) => x * x * x;

  ctx.save();
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  // 1. Clean Modern Dark Aesthetic Gradient Background (Zero glow effects)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, '#0A0A1A');
  bgGrad.addColorStop(0.52, '#161834');
  bgGrad.addColorStop(1, '#05050F');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Timeline Choreography Parameters
  let ringSweep = 0;
  let leafBloom = 0;
  let berryPop = 0;
  let bulbPop = 0;
  let bowReveal = 0;
  let chasePhase = 0;
  let chaseIntensity = 0;
  let wreathRockDeg = 0;
  let tailFlutter = 0;
  let outerAccent = 0;

  if (currentScene === 0) {
    // Scene 1: Core ring trim-path, radial domino leaf bloom, berries, inner lights & scarlet bow
    ringSweep = easeInOutCubic(subP(sceneProgress, 0.02, 0.36));
    leafBloom = easeOutCubic(subP(sceneProgress, 0.14, 0.64));
    berryPop = easeOutCubic(subP(sceneProgress, 0.42, 0.74));
    bulbPop = easeOutCubic(subP(sceneProgress, 0.54, 0.82));
    bowReveal = easeOutCubic(subP(sceneProgress, 0.66, 0.98));
    tailFlutter = loopT * 2.1;
  } else if (currentScene === 1) {
    // Scene 2: Angular comet light-chase, gentle breathing sway, waving bow tails & outer sparks
    ringSweep = 1;
    leafBloom = 1;
    berryPop = 1;
    bulbPop = 1;
    bowReveal = 1;

    chaseIntensity = easeInOutCubic(subP(sceneProgress, 0.02, 0.22));
    chasePhase = (sceneProgress * 2.0) % 1;
    wreathRockDeg = Math.sin(sceneProgress * Math.PI * 2) * 1.6;
    tailFlutter = loopT * 2.1;
    outerAccent = easeInOutCubic(subP(sceneProgress, 0.12, 0.38));
  } else {
    // Scene 3: Dimming comet lights, bow fold, reverse domino leaf collapse back to seed pin
    outerAccent = 1 - easeInOutCubic(subP(sceneProgress, 0.0, 0.30));
    chaseIntensity = 1 - easeInOutCubic(subP(sceneProgress, 0.04, 0.34));
    chasePhase = (sceneProgress * 0.6) % 1;

    bowReveal = 1 - easeInCubic(subP(sceneProgress, 0.28, 0.56));
    bulbPop = 1 - easeInCubic(subP(sceneProgress, 0.38, 0.64));
    berryPop = 1 - easeInCubic(subP(sceneProgress, 0.44, 0.68));
    leafBloom = 1 - easeInOutCubic(subP(sceneProgress, 0.54, 0.86));
    ringSweep = 1 - easeInOutCubic(subP(sceneProgress, 0.76, 1.0));
    tailFlutter = loopT * 2.1;
  }

  // 3. Geometric Layout Constants (Strict 3 radial tracks + dedicated +90deg bow zone)
  const wreathCy = cy - minSide * 0.022;
  const ringR = minSide * 0.205;
  const bowPivotY = wreathCy + ringR;

  // Helper: Draw Stylized Teardrop Leaf at Polar Position
  function drawLeaf(lx, ly, angleRad, len, wid, col, scale) {
    if (scale <= 0.01) return;
    ctx.save();
    ctx.translate(lx, ly);
    ctx.rotate(angleRad);
    ctx.scale(scale, scale);

    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.bezierCurveTo(len * 0.35, -wid * 0.65, len * 0.78, -wid * 0.42, len, 0);
    ctx.bezierCurveTo(len * 0.78, wid * 0.42, len * 0.35, wid * 0.65, 0, 0);
    ctx.closePath();
    ctx.fillStyle = col;
    ctx.fill();

    // Crisp inner leaf vein highlight
    ctx.beginPath();
    ctx.moveTo(len * 0.14, 0);
    ctx.lineTo(len * 0.76, 0);
    ctx.strokeStyle = 'rgba(235, 255, 248, 0.28)';
    ctx.lineWidth = Math.max(1.2, wid * 0.10);
    ctx.stroke();

    ctx.restore();
  }

  // Helper: Draw 4-Point Diamond Spark
  function drawSpark(sx, sy, sz, rot, col, alpha) {
    if (sz <= 0.4 || alpha <= 0.01) return;
    ctx.save();
    ctx.translate(sx, sy);
    ctx.rotate(rot);
    ctx.globalAlpha = alpha;
    ctx.beginPath();
    const inner = sz * 0.30;
    for (let i = 0; i < 8; i++) {
      const a = (i * Math.PI) / 4;
      const r = i % 2 === 0 ? sz : inner;
      if (i === 0) ctx.moveTo(Math.cos(a) * r, Math.sin(a) * r);
      else ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r);
    }
    ctx.closePath();
    ctx.fillStyle = col;
    ctx.fill();
    ctx.restore();
  }

  // 4. Exterior Flanking Rose, Jade & Gold Sparks (Strictly outside outer berry orbit > 0.27 * minSide)
  if (outerAccent > 0.005) {
    const flanks = [
      { x: cx - minSide * 0.35, y: cy - minSide * 0.16, sz: minSide * 0.015, col: '#FFD452' },
      { x: cx - minSide * 0.37, y: cy + minSide * 0.09, sz: minSide * 0.012, col: '#FF80A6' },
      { x: cx + minSide * 0.35, y: cy - minSide * 0.16, sz: minSide * 0.015, col: '#28D498' },
      { x: cx + minSide * 0.37, y: cy + minSide * 0.09, sz: minSide * 0.012, col: '#FFD452' },
    ];
    for (let i = 0; i < flanks.length; i++) {
      const fl = flanks[i];
      const pulse = 0.85 + 0.15 * Math.sin(loopT * Math.PI * 0.9 + i * 1.4);
      drawSpark(fl.x, fl.y, fl.sz * outerAccent * pulse, loopT * 0.5 + i, fl.col, outerAccent * 0.88);
    }
  }

  // 5. Wreath Assembly (Gentle breathing rock around ring center)
  ctx.save();
  ctx.translate(cx, wreathCy);
  ctx.rotate((wreathRockDeg * Math.PI) / 180);
  ctx.translate(-cx, -wreathCy);

  // 5A. Core Structural Pine Ring (Sweeps symmetrically up from +90deg bottom apex)
  if (ringSweep > 0.015) {
    const ringAlpha = subP(ringSweep, 0.015, 0.10);
    const maxHalf = (158 * Math.PI) / 180; // Stops cleanly before +90deg bow zone
    const curHalf = maxHalf * ringSweep;

    ctx.save();
    ctx.globalAlpha = ringAlpha;
    ctx.strokeStyle = '#0D7354';
    ctx.lineWidth = minSide * 0.022;

    // Right branch from top (-90deg) down toward right bottom (+68deg) or bottom up:
    // Sweep cleanly upward from bottom-left (112deg) & bottom-right (68deg) toward top (-90deg)
    ctx.beginPath();
    ctx.arc(cx, wreathCy, ringR, (112 * Math.PI) / 180, (112 * Math.PI) / 180 + curHalf, false);
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(cx, wreathCy, ringR, (68 * Math.PI) / 180, (68 * Math.PI) / 180 - curHalf, true);
    ctx.stroke();
    ctx.restore();
  }

  // 5B. Mid Track (r = ringR): 12 Symmetrical Layered Geometric Pine Leaf Pairs (Strictly in 127..413 deg)
  if (leafBloom > 0.01) {
    const stations = 12;
    for (let i = 0; i < stations; i++) {
      const deg = 127 + i * 26;
      const rad = (deg * Math.PI) / 180;
      // Mirror-symmetric stagger from bottom-up toward top apex
      const distFromBottom = Math.min(i, stations - 1 - i) / 5;
      const st = easeOutCubic(subP(leafBloom, distFromBottom * 0.48, distFromBottom * 0.48 + 0.52));
      if (st <= 0.01) continue;

      const anchorX = cx + Math.cos(rad) * ringR;
      const anchorY = wreathCy + Math.sin(rad) * ringR;
      const tangAngle = rad + Math.PI * 0.5;

      // Inner darker teal leaf (angled slightly inward)
      drawLeaf(anchorX, anchorY, tangAngle - 0.52, minSide * 0.056, minSide * 0.022, '#16A376', st);
      // Outer vibrant jade leaf (angled slightly outward)
      drawLeaf(anchorX, anchorY, tangAngle + 0.48, minSide * 0.066, minSide * 0.025, '#28D498', st);
    }
  }

  // 5C. Outer Track (r = ringR + 0.048*minSide): 6 Scarlet & Rose Berry Pairs in clean notches
  if (berryPop > 0.01) {
    const berryAnglesDeg = [140, 192, 244, 296, 348, 400];
    const outerTrackR = ringR + minSide * 0.048;
    for (let i = 0; i < berryAnglesDeg.length; i++) {
      const deg = berryAnglesDeg[i];
      const rad = (deg * Math.PI) / 180;
      const mirrorIdx = Math.min(i, berryAnglesDeg.length - 1 - i) / 2;
      const bp = easeOutCubic(subP(berryPop, mirrorIdx * 0.35, mirrorIdx * 0.35 + 0.65));
      if (bp <= 0.01) continue;

      const bx = cx + Math.cos(rad) * outerTrackR;
      const by = wreathCy + Math.sin(rad) * outerTrackR;
      const bRad = minSide * 0.0125 * bp;
      const tang = rad + Math.PI * 0.5;
      const off = minSide * 0.009 * bp;

      // Twin berry pair along tangent
      for (let b = -1; b <= 1; b += 2) {
        const px = bx + Math.cos(tang) * off * b;
        const py = by + Math.sin(tang) * off * b;
        ctx.beginPath();
        ctx.arc(px, py, bRad, 0, Math.PI * 2);
        ctx.fillStyle = b < 0 ? '#F23D54' : '#FF80A6';
        ctx.fill();

        // Crisp glossy highlight dot
        ctx.beginPath();
        ctx.arc(px - bRad * 0.30, py - bRad * 0.30, bRad * 0.28, 0, Math.PI * 2);
        ctx.fillStyle = '#FFE8EE';
        ctx.fill();
      }
    }
  }

  // 5D. Inner Track (r = ringR - 0.044*minSide): 8 Comet-Chasing Fairy Light Bulbs
  if (bulbPop > 0.01) {
    const bulbAnglesDeg = [128, 168.5, 209, 249.5, 290.5, 331, 371.5, 412];
    const innerTrackR = ringR - minSide * 0.044;
    const cometAngleDeg = 120 + chasePhase * 300;

    for (let i = 0; i < bulbAnglesDeg.length; i++) {
      const deg = bulbAnglesDeg[i];
      const rad = (deg * Math.PI) / 180;
      const mirrorIdx = Math.min(i, bulbAnglesDeg.length - 1 - i) / 3;
      const bp = easeOutCubic(subP(bulbPop, mirrorIdx * 0.35, mirrorIdx * 0.35 + 0.65));
      if (bp <= 0.01) continue;

      // Angular comet distance with wrap-around across 300-deg arc
      let diff = Math.abs(deg - cometAngleDeg);
      if (diff > 150) diff = 300 - diff;
      const glow = chaseIntensity * Math.exp(-(diff * diff) / (2 * 36 * 36));

      const lx = cx + Math.cos(rad) * innerTrackR;
      const ly = wreathCy + Math.sin(rad) * innerTrackR;
      const lRad = minSide * 0.0135 * bp * (1 + 0.28 * glow);

      // Clean gold socket collar ring around lit bulb
      if (glow > 0.15) {
        ctx.beginPath();
        ctx.arc(lx, ly, lRad * 1.38, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(255, 232, 130, ${(0.34 * glow).toFixed(3)})`;
        ctx.fill();
      }

      ctx.beginPath();
      ctx.arc(lx, ly, lRad, 0, Math.PI * 2);
      ctx.fillStyle = glow > 0.35 ? '#FFF8D6' : '#F2B84B';
      ctx.fill();

      ctx.beginPath();
      ctx.arc(lx, ly, lRad * 0.62, 0, Math.PI * 2);
      ctx.fillStyle = '#FFD452';
      ctx.fill();
    }
  }

  // 5E. Bottom Scarlet Bow & Two Waving Ribbon Tails (Strictly inside +90deg reserved gap)
  if (bowReveal > 0.01) {
    ctx.save();
    ctx.translate(cx, bowPivotY);
    ctx.scale(bowReveal, bowReveal);

    // Two wavy downward-outward ribbon tails (angled ±28deg, strictly clear of bottom leaves)
    const tailLen = minSide * 0.115;
    for (let side = -1; side <= 1; side += 2) {
      const segs = 16;
      ctx.save();
      ctx.beginPath();
      for (let s = 0; s <= segs; s++) {
        const u = s / segs;
        const baseAngle = Math.PI * 0.5 - side * (28 * Math.PI) / 180;
        const dist = u * tailLen;
        const flutter = Math.sin(u * Math.PI * 2.0 - tailFlutter) * (minSide * 0.008) * u;
        const px = Math.cos(baseAngle) * dist + Math.sin(baseAngle) * flutter;
        const py = Math.sin(baseAngle) * dist - Math.cos(baseAngle) * flutter;
        if (s === 0) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
      }
      ctx.strokeStyle = '#C21B35';
      ctx.lineWidth = minSide * 0.022;
      ctx.stroke();

      ctx.strokeStyle = '#FF5970';
      ctx.lineWidth = minSide * 0.0055;
      ctx.stroke();
      ctx.restore();
    }

    // Symmetrical Scarlet Bow Loops
    const loopW = minSide * 0.078;
    const loopH = minSide * 0.042;
    for (let side = -1; side <= 1; side += 2) {
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.bezierCurveTo(
        side * loopW * 0.55,
        -loopH * 1.0,
        side * loopW * 1.10,
        -loopH * 0.55,
        side * loopW,
        loopH * 0.18
      );
      ctx.bezierCurveTo(
        side * loopW * 0.82,
        loopH * 0.58,
        side * loopW * 0.35,
        loopH * 0.32,
        0,
        minSide * 0.006
      );
      ctx.closePath();

      const bowGrad = ctx.createLinearGradient(0, -loopH, side * loopW, loopH);
      bowGrad.addColorStop(0, '#FF5C72');
      bowGrad.addColorStop(0.55, '#F23D54');
      bowGrad.addColorStop(1, '#B3152E');
      ctx.fillStyle = bowGrad;
      ctx.fill();
    }

    // Center Bow Knot
    const knotSize = minSide * 0.032;
    ctx.beginPath();
    ctx.roundRect(-knotSize * 0.5, -knotSize * 0.45, knotSize, knotSize * 0.90, knotSize * 0.34);
    ctx.fillStyle = '#FF6E82';
    ctx.fill();

    ctx.restore();
  }

  // Seamless Bottom Center Finial Seed Pin (Always present at t=0 and t=20)
  ctx.beginPath();
  ctx.arc(cx, bowPivotY, minSide * 0.009, 0, Math.PI * 2);
  ctx.fillStyle = '#FFD452';
  ctx.fill();

  ctx.restore(); // End Wreath Rock Group
  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.min(sceneCount - 1, Math.floor(loopT / sceneDuration));
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const subP = (p, a, b) => clamp01((p - a) / (b - a));
  const easeInOutCubic = (x) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2);
  const easeOutCubic = (x) => 1 - Math.pow(1 - x, 3);
  const easeInCubic = (x) => x * x * x;

  ctx.save();
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  // 1. Clean Modern Dark Aesthetic Gradient Background (Zero glow effects)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, '#0A0F0A');
  bgGrad.addColorStop(0.52, '#162317');
  bgGrad.addColorStop(1, '#060906');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Timeline Choreography Parameters
  let stockScale = 0;
  let stockAlpha = 0;
  let chevronTrim = 0;
  let starStitch = 0;
  let treatPop = 0;
  let swayDeg = 0;
  let outerAccent = 0;

  if (currentScene === 0) {
    // Scene 1: Stocking body & cuff reveal, animated knitted chevron & star stitch trim-path
    stockScale = easeOutCubic(subP(sceneProgress, 0.02, 0.34));
    stockAlpha = easeInOutCubic(subP(sceneProgress, 0.02, 0.24));
    swayDeg = Math.sin(subP(sceneProgress, 0.02, 0.52) * Math.PI) * 3.0;

    chevronTrim = easeInOutCubic(subP(sceneProgress, 0.34, 0.72));
    starStitch = easeOutCubic(subP(sceneProgress, 0.54, 0.94));
  } else if (currentScene === 1) {
    // Scene 2: Pop-out holiday treats from cuff (parcel, candy cane, pine sprig) + subtle sway
    stockScale = 1;
    stockAlpha = 1;
    chevronTrim = 1;
    starStitch = 1;

    swayDeg = Math.sin(sceneProgress * Math.PI * 2) * 1.4;
    treatPop = easeOutCubic(subP(sceneProgress, 0.04, 0.44));
    outerAccent = easeInOutCubic(subP(sceneProgress, 0.16, 0.44));
  } else {
    // Scene 3: Treats tuck back into cuff, stitch clean-sweep, seamless return to anchor pin
    outerAccent = 1 - easeInOutCubic(subP(sceneProgress, 0.0, 0.30));
    treatPop = 1 - easeInCubic(subP(sceneProgress, 0.10, 0.48));
    swayDeg = Math.sin(subP(sceneProgress, 0.0, 0.48) * Math.PI) * -2.2;

    starStitch = 1 - easeInOutCubic(subP(sceneProgress, 0.42, 0.68));
    chevronTrim = 1 - easeInOutCubic(subP(sceneProgress, 0.50, 0.76));
    stockScale = 1 - easeInCubic(subP(sceneProgress, 0.72, 0.98));
    stockAlpha = 1 - easeInOutCubic(subP(sceneProgress, 0.72, 0.96));
  }

  // 3. Geometric Layout Constants (16:9 centered around cx, balanced cuff + toe)
  const stockCx = cx - minSide * 0.028;
  const cuffW = minSide * 0.220;
  const cuffH = minSide * 0.078;
  const cuffTop = cy - minSide * 0.120;
  const cuffBot = cuffTop + cuffH;
  const pivotX = stockCx - cuffW * 0.44;
  const pivotY = cuffTop - minSide * 0.042;
  const soleY = cy + minSide * 0.285;

  // Helper: Draw 4-Point Stitch Star
  function drawStar(sx, sy, rad, rot, col, alpha) {
    if (rad <= 0.4 || alpha <= 0.01) return;
    ctx.save();
    ctx.translate(sx, sy);
    ctx.rotate(rot);
    ctx.globalAlpha = alpha;
    ctx.beginPath();
    const inner = rad * 0.32;
    for (let i = 0; i < 8; i++) {
      const a = (i * Math.PI) / 4;
      const r = i % 2 === 0 ? rad : inner;
      if (i === 0) ctx.moveTo(Math.cos(a) * r, Math.sin(a) * r);
      else ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r);
    }
    ctx.closePath();
    ctx.fillStyle = col;
    ctx.fill();
    ctx.restore();
  }

  // Helper: Trace Clean Modern Flat Vector Stocking Boot Silhouette
  function traceBootPath() {
    const legL = stockCx - cuffW * 0.44;
    const legR = stockCx + cuffW * 0.44;
    const ankleY = cy + minSide * 0.105;
    const toeTipX = stockCx + minSide * 0.188;
    const toeTopY = cy + minSide * 0.135;

    ctx.beginPath();
    ctx.moveTo(legL, cuffBot - minSide * 0.012);
    ctx.lineTo(legR, cuffBot - minSide * 0.012);
    ctx.lineTo(legR, ankleY - minSide * 0.020);
    // Smooth instep curve into rounded toe top
    ctx.quadraticCurveTo(legR, toeTopY, legR + minSide * 0.048, toeTopY);
    // Generous rounded toe cap
    ctx.bezierCurveTo(
      toeTipX + minSide * 0.018,
      toeTopY,
      toeTipX + minSide * 0.018,
      soleY,
      legR + minSide * 0.020,
      soleY
    );
    // Smooth sole & rounded heel back up to left leg wall
    ctx.lineTo(legL + minSide * 0.055, soleY);
    ctx.quadraticCurveTo(legL - minSide * 0.012, soleY, legL, soleY - minSide * 0.072);
    ctx.closePath();
  }

  // Helper: Draw Mini Clipped Peppermint Candy Cane Treat
  function drawMiniCandyCane(px, py, angle, alpha) {
    if (alpha <= 0.01) return;
    ctx.save();
    ctx.translate(px, py);
    ctx.rotate(angle);
    ctx.globalAlpha = alpha;

    const hw = minSide * 0.010;
    const stemBot = minSide * 0.095;
    const stemTop = minSide * 0.055;
    const hookR = minSide * 0.024;
    const tipDrop = minSide * 0.014;

    const traceContour = () => {
      ctx.beginPath();
      ctx.arc(0, stemBot, hw, 0, Math.PI, false);
      ctx.lineTo(-hw, -stemTop);
      ctx.arc(hookR, -stemTop, hookR + hw, Math.PI, 0, false);
      ctx.lineTo(hookR * 2 + hw, -stemTop + tipDrop);
      ctx.arc(hookR * 2, -stemTop + tipDrop, hw, 0, Math.PI, false);
      ctx.lineTo(hookR * 2 - hw, -stemTop);
      ctx.arc(hookR, -stemTop, hookR - hw, 0, Math.PI, true);
      ctx.lineTo(hw, stemBot);
      ctx.closePath();
    };

    ctx.save();
    traceContour();
    ctx.clip();
    ctx.fillStyle = '#F5ECE0';
    ctx.fillRect(-hw * 2, -stemTop - hookR - hw * 2, hookR * 2 + hw * 4, stemBot + stemTop + hookR + hw * 4);

    ctx.save();
    ctx.rotate(-Math.PI / 4);
    const pitch = minSide * 0.032;
    for (let y = -minSide * 0.25; y < minSide * 0.25; y += pitch) {
      ctx.fillStyle = '#E63946';
      ctx.fillRect(-minSide * 0.2, y, minSide * 0.4, pitch * 0.36);
      ctx.fillStyle = '#4AA87C';
      ctx.fillRect(-minSide * 0.2, y + pitch * 0.52, minSide * 0.4, pitch * 0.16);
    }
    ctx.restore();
    ctx.restore();

    traceContour();
    ctx.strokeStyle = '#182419';
    ctx.lineWidth = minSide * 0.0032;
    ctx.stroke();
    ctx.restore();
  }

  // Helper: Draw Mini Wrapped Mustard-Gold Gift Parcel Treat
  function drawMiniParcel(px, py, alpha) {
    if (alpha <= 0.01) return;
    ctx.save();
    ctx.translate(px, py);
    ctx.rotate(-0.10);
    ctx.globalAlpha = alpha;

    const sz = minSide * 0.056;
    ctx.beginPath();
    ctx.roundRect(-sz * 0.5, -sz * 0.5, sz, sz * 1.15, sz * 0.14);
    ctx.fillStyle = '#F2B84B';
    ctx.fill();

    ctx.save();
    ctx.clip();
    ctx.fillStyle = '#E63946';
    ctx.fillRect(-sz * 0.12, -sz * 0.55, sz * 0.24, sz * 1.25);
    ctx.fillRect(-sz * 0.55, -sz * 0.12, sz * 1.1, sz * 0.22);
    ctx.restore();

    // Small bow top
    for (let s = -1; s <= 1; s += 2) {
      ctx.beginPath();
      ctx.ellipse(s * sz * 0.18, -sz * 0.55, sz * 0.18, sz * 0.10, s * -0.35, 0, Math.PI * 2);
      ctx.fillStyle = '#FF5C6C';
      ctx.fill();
    }
    ctx.restore();
  }

  // Helper: Draw Pine & Holly Berry Sprig Treat
  function drawPineSprig(px, py, alpha) {
    if (alpha <= 0.01) return;
    ctx.save();
    ctx.translate(px, py);
    ctx.rotate(0.32);
    ctx.globalAlpha = alpha;

    const leafLen = minSide * 0.062;
    const leafW = minSide * 0.018;
    const angles = [-0.42, 0.0, 0.42];
    const cols = ['#2A7554', '#4AA87C', '#2A7554'];

    for (let i = 0; i < 3; i++) {
      ctx.save();
      ctx.rotate(angles[i]);
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.quadraticCurveTo(-leafW, -leafLen * 0.55, 0, -leafLen);
      ctx.quadraticCurveTo(leafW, -leafLen * 0.55, 0, 0);
      ctx.closePath();
      ctx.fillStyle = cols[i];
      ctx.fill();
      ctx.restore();
    }

    // Two glossy Crimson berries at sprig base
    const bR = minSide * 0.011;
    ctx.beginPath();
    ctx.arc(-bR * 0.7, -bR * 0.4, bR, 0, Math.PI * 2);
    ctx.arc(bR * 0.7, -bR * 0.3, bR, 0, Math.PI * 2);
    ctx.fillStyle = '#E63946';
    ctx.fill();

    ctx.restore();
  }

  // 4. Exterior Flanking Gold & Sage Sparks (Strictly outside stocking silhouette & cuff)
  if (outerAccent > 0.005) {
    const flanks = [
      { x: cx - minSide * 0.30, y: cy - minSide * 0.14, sz: minSide * 0.015, col: '#F2B84B' },
      { x: cx - minSide * 0.28, y: cy + minSide * 0.12, sz: minSide * 0.012, col: '#4AA87C' },
      { x: cx + minSide * 0.30, y: cy - minSide * 0.12, sz: minSide * 0.015, col: '#4AA87C' },
      { x: cx + minSide * 0.32, y: cy + minSide * 0.14, sz: minSide * 0.012, col: '#E63946' },
    ];
    for (let i = 0; i < flanks.length; i++) {
      const fl = flanks[i];
      const pulse = 0.85 + 0.15 * Math.sin(loopT * Math.PI * 0.9 + i * 1.4);
      drawStar(fl.x, fl.y, fl.sz * outerAccent * pulse, loopT * 0.5 + i, fl.col, outerAccent * 0.88);
    }
  }

  // 5. Suspended Stocking Group (Pivots cleanly from top-left hanging loop pin)
  ctx.save();
  ctx.translate(pivotX, pivotY);
  ctx.rotate((swayDeg * Math.PI) / 180);
  ctx.translate(-pivotX, -pivotY);

  if (stockScale > 0.01 && stockAlpha > 0.01) {
    ctx.save();
    ctx.translate(pivotX, pivotY);
    ctx.scale(stockScale, stockScale);
    ctx.translate(-pivotX, -pivotY);
    ctx.globalAlpha = stockAlpha;

    // 5A. Closed Teardrop Hanging Loop Strap (Drawn behind cuff corner)
    ctx.beginPath();
    ctx.moveTo(pivotX, pivotY);
    ctx.bezierCurveTo(
      pivotX - minSide * 0.022,
      pivotY + minSide * 0.022,
      pivotX - minSide * 0.012,
      cuffTop + minSide * 0.015,
      pivotX + minSide * 0.008,
      cuffTop + minSide * 0.018
    );
    ctx.moveTo(pivotX, pivotY);
    ctx.bezierCurveTo(
      pivotX + minSide * 0.016,
      pivotY + minSide * 0.012,
      pivotX + minSide * 0.024,
      cuffTop + minSide * 0.006,
      pivotX + minSide * 0.026,
      cuffTop + minSide * 0.018
    );
    ctx.strokeStyle = '#F2B84B';
    ctx.lineWidth = minSide * 0.0085;
    ctx.stroke();

    // 5B. Pop-Out Holiday Treats (Strictly clipped ABOVE cuffTop + 0.012 so they emerge inside cuff!)
    if (treatPop > 0.01) {
      ctx.save();
      ctx.beginPath();
      ctx.rect(stockCx - cuffW, cy - minSide * 0.45, cuffW * 2.5, cuffTop + minSide * 0.018 - (cy - minSide * 0.45));
      ctx.clip();

      const p1 = easeOutCubic(subP(treatPop, 0.0, 0.72));
      const p2 = easeOutCubic(subP(treatPop, 0.14, 0.86));
      const p3 = easeOutCubic(subP(treatPop, 0.28, 1.0));

      const restY = cuffTop + minSide * 0.065;
      // Left-Center Mini Parcel (Clear of hanging loop on left & candy cane on right)
      const parcelY = restY + (cy - minSide * 0.175 - restY) * p1;
      drawMiniParcel(stockCx - minSide * 0.034, parcelY, clamp01(p1 * 1.4));

      // Center-High Candy Cane
      const caneY = restY + (cy - minSide * 0.205 - restY) * p2;
      drawMiniCandyCane(stockCx + minSide * 0.016, caneY, 0.12, clamp01(p2 * 1.4));

      // Right Pine & Berry Sprig (Berries clear above cuff top)
      const sprigY = restY + (cy - minSide * 0.132 - restY) * p3;
      drawPineSprig(stockCx + minSide * 0.074, sprigY, clamp01(p3 * 1.4));

      ctx.restore();
    }

    // 5C. Crimson Berry Stocking Boot Body + Clipped Toe/Heel Patches & Knitted Patterns
    ctx.save();
    traceBootPath();
    const bootGrad = ctx.createLinearGradient(stockCx - cuffW * 0.5, cuffTop, stockCx + minSide * 0.18, soleY);
    bootGrad.addColorStop(0, '#EA4350');
    bootGrad.addColorStop(0.55, '#D12636');
    bootGrad.addColorStop(1, '#A11725');
    ctx.fillStyle = bootGrad;
    ctx.fill();

    // Clip interior details strictly inside stocking boot
    ctx.clip();

    const legL = stockCx - cuffW * 0.44;
    const legR = stockCx + cuffW * 0.44;

    // Warm Oatmeal Cream Heel Patch (bottom-left corner)
    ctx.beginPath();
    ctx.arc(legL, soleY, minSide * 0.095, -Math.PI * 0.5, 0, false);
    ctx.lineTo(legL, soleY);
    ctx.closePath();
    ctx.fillStyle = '#F5ECE0';
    ctx.fill();

    // Warm Oatmeal Cream Toe Cap Patch (far-right rounded toe)
    ctx.beginPath();
    ctx.arc(stockCx + minSide * 0.188, (cy + minSide * 0.135 + soleY) * 0.5, minSide * 0.088, 0, Math.PI * 2);
    ctx.fillStyle = '#F5ECE0';
    ctx.fill();

    // Band 1: Animated Knitted Mustard-Gold Chevron Trim-Path across upper calf
    if (chevronTrim > 0.01) {
      const zY = cy - minSide * 0.002;
      const zAmp = minSide * 0.014;
      const steps = 6;
      const startX = legL + minSide * 0.016;
      const endX = legR - minSide * 0.016;
      const totalSpan = endX - startX;

      ctx.beginPath();
      for (let s = 0; s <= steps; s++) {
        const u = s / steps;
        if (u > chevronTrim) {
          const prevU = (s - 1) / steps;
          const prevY = zY + ((s - 1) % 2 === 0 ? -zAmp : zAmp);
          const nextY = zY + (s % 2 === 0 ? -zAmp : zAmp);
          const frac = (chevronTrim - prevU) / (u - prevU);
          ctx.lineTo(startX + chevronTrim * totalSpan, prevY + (nextY - prevY) * frac);
          break;
        }
        const px = startX + u * totalSpan;
        const py = zY + (s % 2 === 0 ? -zAmp : zAmp);
        if (s === 0) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
      }
      ctx.strokeStyle = '#F2B84B';
      ctx.lineWidth = minSide * 0.0075;
      ctx.stroke();
    }

    // Band 2: 4 Sequential Oatmeal Cream Knit Stars across lower calf (clear of heel & chevron)
    if (starStitch > 0.01) {
      const starY = cy + minSide * 0.068;
      const count = 4;
      const leftPad = legL + minSide * 0.036;
      const rightPad = legR - minSide * 0.036;
      for (let s = 0; s < count; s++) {
        const pop = easeOutCubic(subP(starStitch, s * 0.16, s * 0.16 + 0.45));
        if (pop <= 0.01) continue;
        const sx = leftPad + (s / (count - 1)) * (rightPad - leftPad);
        drawStar(sx, starY, minSide * 0.014 * pop, 0, '#F5ECE0', pop);
      }
    }

    // Subtle soft shadow right under fluffy cuff lip
    ctx.fillStyle = 'rgba(20, 8, 8, 0.22)';
    ctx.fillRect(legL - 4, cuffBot - minSide * 0.012, cuffW + 8, minSide * 0.022);

    ctx.restore(); // End Boot Clip

    // 5D. Fluffy Scalloped Oatmeal Cream Cuff (Overlaps top edge of boot & treat stems cleanly)
    const cuffGrad = ctx.createLinearGradient(stockCx - cuffW * 0.5, cuffTop, stockCx - cuffW * 0.5, cuffBot);
    cuffGrad.addColorStop(0, '#FFFDF9');
    cuffGrad.addColorStop(0.7, '#F5ECE0');
    cuffGrad.addColorStop(1, '#DFD0BC');

    ctx.beginPath();
    ctx.roundRect(stockCx - cuffW * 0.5, cuffTop, cuffW, cuffH, cuffH * 0.36);
    ctx.fillStyle = cuffGrad;
    ctx.fill();

    // Subtle Sage Green knit trim stitch across cuff center
    ctx.beginPath();
    ctx.moveTo(stockCx - cuffW * 0.36, cuffTop + cuffH * 0.50);
    ctx.lineTo(stockCx + cuffW * 0.36, cuffTop + cuffH * 0.50);
    ctx.strokeStyle = '#4AA87C';
    ctx.lineWidth = minSide * 0.0055;
    ctx.setLineDash([minSide * 0.014, minSide * 0.014]);
    ctx.stroke();
    ctx.setLineDash([]);

    ctx.restore();
  }

  // Seamless Top Anchor Finial Pin (Always present at t=0 and t=20)
  ctx.beginPath();
  ctx.arc(pivotX, pivotY, minSide * 0.009, 0, Math.PI * 2);
  ctx.fillStyle = '#FFE08A';
  ctx.fill();

  ctx.restore(); // End Sway Group
  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.min(sceneCount - 1, Math.floor(loopT / sceneDuration));
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const subP = (p, a, b) => clamp01((p - a) / (b - a));
  const easeInOutCubic = (x) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2);
  const easeOutCubic = (x) => 1 - Math.pow(1 - x, 3);
  const easeInCubic = (x) => x * x * x;

  ctx.save();
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  // 1. Clean Modern Dark Aesthetic Gradient Background (Zero glow effects)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, '#14060A');
  bgGrad.addColorStop(0.52, '#280D16');
  bgGrad.addColorStop(1, '#090305');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Timeline Choreography Parameters
  let frameScale = 0;
  let frameAlpha = 0;
  let candleReveal = 0;
  let flameScale = 0;
  let frostProgress = 0;
  let emberAlpha = 0;
  let swingDeg = 0;
  let outerAccent = 0;

  if (currentScene === 0) {
    // Scene 1: Lantern frame emergence, candle pillar rise, organic flame ignition
    frameScale = easeOutCubic(subP(sceneProgress, 0.02, 0.36));
    frameAlpha = easeInOutCubic(subP(sceneProgress, 0.02, 0.24));
    candleReveal = easeOutCubic(subP(sceneProgress, 0.34, 0.68));
    flameScale = easeOutCubic(subP(sceneProgress, 0.64, 0.98));
  } else if (currentScene === 1) {
    // Scene 2: Organic morphing flame, corner frost crystal growth, rising micro-embers & outer sparks
    frameScale = 1;
    frameAlpha = 1;
    candleReveal = 1;
    flameScale = 1;

    frostProgress = easeInOutCubic(subP(sceneProgress, 0.06, 0.52));
    emberAlpha = easeInOutCubic(subP(sceneProgress, 0.14, 0.38));
    outerAccent = easeInOutCubic(subP(sceneProgress, 0.18, 0.44));
  } else {
    // Scene 3: Graceful pendulum lantern sway, frost melt, flame extinguish & seamless reset
    const swingWin = subP(sceneProgress, 0.0, 0.52);
    const swingEnv = Math.sin(swingWin * Math.PI);
    swingDeg = Math.sin(swingWin * Math.PI * 2) * swingEnv * 3.8;

    outerAccent = 1 - easeInOutCubic(subP(sceneProgress, 0.04, 0.34));
    emberAlpha = 1 - easeInOutCubic(subP(sceneProgress, 0.12, 0.42));
    frostProgress = 1 - easeInOutCubic(subP(sceneProgress, 0.28, 0.60));
    flameScale = 1 - easeInCubic(subP(sceneProgress, 0.48, 0.70));
    candleReveal = 1 - easeInCubic(subP(sceneProgress, 0.62, 0.82));
    frameScale = 1 - easeInCubic(subP(sceneProgress, 0.74, 0.98));
    frameAlpha = 1 - easeInOutCubic(subP(sceneProgress, 0.74, 0.96));
  }

  // 3. Geometric Layout Constants (16:9 centered, suspended cleanly from top finial)
  const pivotY = cy - minSide * 0.305;
  const ringR = minSide * 0.021;
  const ringCy = pivotY + ringR;
  const roofTopY = ringCy + ringR * 0.75;
  const roofBaseY = cy - minSide * 0.142;
  const glassTopY = roofBaseY;
  const glassBotY = cy + minSide * 0.212;
  const baseBotY = cy + minSide * 0.288;

  const glassOuterW = minSide * 0.240;
  const frameStroke = minSide * 0.011;
  const innerGlassW = glassOuterW - frameStroke * 2.2;
  const innerGlassTop = glassTopY + minSide * 0.014;
  const innerGlassBot = glassBotY - minSide * 0.014;
  const innerGlassH = innerGlassBot - innerGlassTop;

  // Helper: Crisp 4-point diamond spark
  function drawSpark(sx, sy, sz, rot, col, alpha) {
    if (sz <= 0.4 || alpha <= 0.01) return;
    ctx.save();
    ctx.translate(sx, sy);
    ctx.rotate(rot);
    ctx.globalAlpha = alpha;
    ctx.beginPath();
    const inner = sz * 0.30;
    for (let i = 0; i < 8; i++) {
      const a = (i * Math.PI) / 4;
      const r = i % 2 === 0 ? sz : inner;
      if (i === 0) ctx.moveTo(Math.cos(a) * r, Math.sin(a) * r);
      else ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r);
    }
    ctx.closePath();
    ctx.fillStyle = col;
    ctx.fill();
    ctx.restore();
  }

  // Helper: Draw Corner Frost Crystal Branch (Grows smoothly outward from corner node)
  function drawCornerFrost(cornerX, cornerY, dirX, dirY, prog) {
    if (prog <= 0.01) return;
    const maxLen = minSide * 0.036;
    const len = maxLen * prog;
    const diagX = cornerX + dirX * len * 0.707;
    const diagY = cornerY + dirY * len * 0.707;

    ctx.save();
    ctx.strokeStyle = '#CBE0FF';
    ctx.lineWidth = Math.max(1.5, minSide * 0.0028);
    ctx.globalAlpha = 0.85 * prog;

    // Main diagonal crystal stem
    ctx.beginPath();
    ctx.moveTo(cornerX, cornerY);
    ctx.lineTo(diagX, diagY);
    ctx.stroke();

    // Two side V-branches along diagonal
    if (prog > 0.32) {
      const bP = subP(prog, 0.32, 1.0);
      const midX = cornerX + dirX * len * 0.40;
      const midY = cornerY + dirY * len * 0.40;
      const armLen = maxLen * 0.34 * bP;

      ctx.beginPath();
      ctx.moveTo(midX, midY);
      ctx.lineTo(midX + dirX * armLen * 0.92, midY + dirY * armLen * 0.12);
      ctx.moveTo(midX, midY);
      ctx.lineTo(midX + dirX * armLen * 0.12, midY + dirY * armLen * 0.92);
      ctx.stroke();
    }

    // Small crisp tip dot
    if (prog > 0.75) {
      ctx.beginPath();
      ctx.arc(diagX, diagY, minSide * 0.0024 * prog, 0, Math.PI * 2);
      ctx.fillStyle = '#EEF5FF';
      ctx.fill();
    }
    ctx.restore();
  }

  // 4. Exterior Flanking Amber & Frost Sparks (Strictly outside swing corridor)
  if (outerAccent > 0.005) {
    const flanks = [
      { x: cx - minSide * 0.28, y: cy - minSide * 0.12, sz: minSide * 0.015, col: '#FFE49E' },
      { x: cx - minSide * 0.31, y: cy + minSide * 0.10, sz: minSide * 0.012, col: '#A5C4FF' },
      { x: cx + minSide * 0.28, y: cy - minSide * 0.12, sz: minSide * 0.015, col: '#A5C4FF' },
      { x: cx + minSide * 0.31, y: cy + minSide * 0.10, sz: minSide * 0.012, col: '#FFB732' },
    ];
    for (let i = 0; i < flanks.length; i++) {
      const fl = flanks[i];
      const pulse = 0.85 + 0.15 * Math.sin(loopT * Math.PI * 0.9 + i * 1.4);
      drawSpark(fl.x, fl.y, fl.sz * outerAccent * pulse, loopT * 0.5 + i, fl.col, outerAccent * 0.88);
    }
  }

  // 5. Suspended Lantern Pendulum Group (Rotates cleanly around top finial pivot)
  ctx.save();
  ctx.translate(cx, pivotY);
  ctx.rotate((swingDeg * Math.PI) / 180);
  ctx.translate(-cx, -pivotY);

  if (frameScale > 0.01 && frameAlpha > 0.01) {
    ctx.save();
    ctx.translate(cx, pivotY);
    ctx.scale(frameScale, frameScale);
    ctx.translate(-cx, -pivotY);
    ctx.globalAlpha = frameAlpha;

    // 5A. Top Hanging Ring
    ctx.beginPath();
    ctx.arc(cx, ringCy, ringR, 0, Math.PI * 2);
    ctx.strokeStyle = '#D99E5B';
    ctx.lineWidth = minSide * 0.0065;
    ctx.stroke();

    // 5B. Glass Chamber Interior (Strictly clipped inside glass window)
    ctx.save();
    ctx.beginPath();
    ctx.roundRect(cx - innerGlassW * 0.5, innerGlassTop, innerGlassW, innerGlassH, minSide * 0.008);
    ctx.clip();

    // Recessed Dark Glass Chamber Backdrop
    const chamberGrad = ctx.createLinearGradient(cx, innerGlassTop, cx, innerGlassBot);
    chamberGrad.addColorStop(0, '#1C0B12');
    chamberGrad.addColorStop(0.55, '#2A101B');
    chamberGrad.addColorStop(1, '#19080E');
    ctx.fillStyle = chamberGrad;
    ctx.fillRect(cx - innerGlassW * 0.5, innerGlassTop, innerGlassW, innerGlassH);

    // Subtle interior warm chamber light spill (strictly inside glass, zero background glow)
    if (flameScale > 0.02) {
      const coneTopY = cy + minSide * 0.032 - minSide * 0.095 * flameScale;
      const coneGrad = ctx.createRadialGradient(
        cx,
        cy + minSide * 0.01,
        minSide * 0.008,
        cx,
        cy + minSide * 0.01,
        innerGlassW * 0.65
      );
      coneGrad.addColorStop(0, `rgba(255, 196, 84, ${(0.22 * flameScale).toFixed(3)})`);
      coneGrad.addColorStop(0.65, `rgba(255, 128, 48, ${(0.08 * flameScale).toFixed(3)})`);
      coneGrad.addColorStop(1, 'rgba(255, 128, 48, 0.0)');
      ctx.fillStyle = coneGrad;
      ctx.fillRect(cx - innerGlassW * 0.5, coneTopY - minSide * 0.04, innerGlassW, innerGlassH);
    }

    // 4 Corner Frost Crystals (Strictly tucked in 4 corners, clear of candle & flame)
    if (frostProgress > 0.01) {
      const pad = minSide * 0.008;
      drawCornerFrost(cx - innerGlassW * 0.5 + pad, innerGlassTop + pad, 1, 1, frostProgress);
      drawCornerFrost(cx + innerGlassW * 0.5 - pad, innerGlassTop + pad, -1, 1, frostProgress);
      drawCornerFrost(cx - innerGlassW * 0.5 + pad, innerGlassBot - pad, 1, -1, frostProgress);
      drawCornerFrost(cx + innerGlassW * 0.5 - pad, innerGlassBot - pad, -1, -1, frostProgress);
    }

    // Wax Candle Pillar + Scalloped Melt Rim + Wick
    if (candleReveal > 0.01) {
      const candleW = minSide * 0.072;
      const maxCandleH = minSide * 0.146;
      const curCandleH = maxCandleH * candleReveal;
      const candleTopY = innerGlassBot - curCandleH;

      const waxGrad = ctx.createLinearGradient(cx - candleW * 0.5, candleTopY, cx + candleW * 0.5, candleTopY);
      waxGrad.addColorStop(0, '#FFF8EB');
      waxGrad.addColorStop(0.65, '#F2E2CA');
      waxGrad.addColorStop(1, '#D1BBA0');

      ctx.beginPath();
      ctx.roundRect(cx - candleW * 0.5, candleTopY, candleW, curCandleH + 4, [minSide * 0.008, minSide * 0.008, 0, 0]);
      ctx.fillStyle = waxGrad;
      ctx.fill();

      // Subtle flat-vector wax drip wave along left-center front rim
      ctx.beginPath();
      ctx.moveTo(cx - candleW * 0.5, candleTopY + minSide * 0.008);
      ctx.lineTo(cx - candleW * 0.5, candleTopY + minSide * 0.028 * candleReveal);
      ctx.arc(cx - candleW * 0.34, candleTopY + minSide * 0.028 * candleReveal, candleW * 0.16, Math.PI, 0, true);
      ctx.arc(cx - candleW * 0.06, candleTopY + minSide * 0.020 * candleReveal, candleW * 0.12, Math.PI, 0, true);
      ctx.lineTo(cx + candleW * 0.5, candleTopY + minSide * 0.008);
      ctx.closePath();
      ctx.fillStyle = '#FFFDF9';
      ctx.fill();

      // Dark Wick
      const wickH = minSide * 0.018 * candleReveal;
      ctx.beginPath();
      ctx.moveTo(cx, candleTopY);
      ctx.lineTo(cx, candleTopY - wickH);
      ctx.strokeStyle = '#3B2318';
      ctx.lineWidth = minSide * 0.0042;
      ctx.stroke();

      // 2-Layer Organic Morphing Flame (Tip strictly below glassTop)
      if (flameScale > 0.01) {
        const wickTipY = candleTopY - wickH;
        const sway1 = Math.sin(loopT * 3.1) * (minSide * 0.0065);
        const sway2 = Math.cos(loopT * 4.7) * (minSide * 0.0028);
        const tipShiftX = (sway1 + sway2) * flameScale;
        const flameH = minSide * (0.090 + 0.005 * Math.sin(loopT * 3.8)) * flameScale;
        const flameHalfW = minSide * 0.024 * flameScale;

        // Outer Molten Amber-Orange Teardrop
        const outerGrad = ctx.createLinearGradient(cx, wickTipY - flameH, cx, wickTipY);
        outerGrad.addColorStop(0, '#FFE48A');
        outerGrad.addColorStop(0.55, '#FF9E2C');
        outerGrad.addColorStop(1, '#F25C24');

        ctx.beginPath();
        ctx.moveTo(cx, wickTipY + minSide * 0.004);
        ctx.bezierCurveTo(
          cx + flameHalfW * 1.25,
          wickTipY - flameH * 0.15,
          cx + flameHalfW * 0.85 + tipShiftX * 0.45,
          wickTipY - flameH * 0.62,
          cx + tipShiftX,
          wickTipY - flameH
        );
        ctx.bezierCurveTo(
          cx - flameHalfW * 0.85 + tipShiftX * 0.45,
          wickTipY - flameH * 0.62,
          cx - flameHalfW * 1.25,
          wickTipY - flameH * 0.15,
          cx,
          wickTipY + minSide * 0.004
        );
        ctx.closePath();
        ctx.fillStyle = outerGrad;
        ctx.fill();

        // Inner Luminous Cream-White Core
        const coreH = flameH * 0.56;
        const coreW = flameHalfW * 0.52;
        ctx.beginPath();
        ctx.moveTo(cx, wickTipY + minSide * 0.001);
        ctx.bezierCurveTo(
          cx + coreW * 1.2,
          wickTipY - coreH * 0.18,
          cx + coreW * 0.8 + tipShiftX * 0.25,
          wickTipY - coreH * 0.64,
          cx + tipShiftX * 0.45,
          wickTipY - coreH
        );
        ctx.bezierCurveTo(
          cx - coreW * 0.8 + tipShiftX * 0.25,
          wickTipY - coreH * 0.64,
          cx - coreW * 1.2,
          wickTipY - coreH * 0.18,
          cx,
          wickTipY + minSide * 0.001
        );
        ctx.closePath();
        ctx.fillStyle = '#FFF8D6';
        ctx.fill();

        // 2 Subtle Rising Embers Strictly Between Flame Tip & Upper Glass Wall
        if (emberAlpha > 0.01) {
          for (let e = 0; e < 2; e++) {
            const u = (loopT * 0.45 + e * 0.5) % 1;
            const eY = (wickTipY - flameH - minSide * 0.012) - u * (minSide * 0.042);
            if (eY > innerGlassTop + minSide * 0.012) {
              const eX = cx + Math.sin(u * Math.PI * 2 + e * 2.1) * (minSide * 0.012);
              const eFade = Math.sin(u * Math.PI) * emberAlpha * 0.85;
              ctx.beginPath();
              ctx.arc(eX, eY, minSide * (0.0032 * (1 - u * 0.4)), 0, Math.PI * 2);
              ctx.fillStyle = `rgba(255, 224, 130, ${eFade.toFixed(3)})`;
              ctx.fill();
            }
          }
        }
      }
    }

    // Subtle Vertical Glass Highlight Strip inside Left Chamber Edge (Clear of frost crystals)
    ctx.save();
    ctx.globalAlpha = 0.20;
    ctx.beginPath();
    ctx.roundRect(
      cx - innerGlassW * 0.40,
      innerGlassTop + innerGlassH * 0.18,
      minSide * 0.009,
      innerGlassH * 0.64,
      minSide * 0.0045
    );
    ctx.fillStyle = '#FFFFFF';
    ctx.fill();
    ctx.restore();

    ctx.restore(); // End Glass Chamber Clip

    // 5C. Lantern Bronze Outer Frame Posts & Crossbars
    ctx.beginPath();
    ctx.roundRect(cx - glassOuterW * 0.5, glassTopY, glassOuterW, glassBotY - glassTopY, minSide * 0.012);
    ctx.strokeStyle = '#BA8249';
    ctx.lineWidth = frameStroke;
    ctx.stroke();

    // Inner subtle gold rim outline around glass bay
    ctx.beginPath();
    ctx.roundRect(cx - innerGlassW * 0.5, innerGlassTop, innerGlassW, innerGlassH, minSide * 0.008);
    ctx.strokeStyle = '#6E4521';
    ctx.lineWidth = minSide * 0.0032;
    ctx.stroke();

    // 5D. 2-Tier Beveled Bronze Lantern Roof
    const roofGrad = ctx.createLinearGradient(cx - glassOuterW * 0.6, roofTopY, cx + glassOuterW * 0.6, roofBaseY);
    roofGrad.addColorStop(0, '#E3AC6B');
    roofGrad.addColorStop(0.5, '#BA8249');
    roofGrad.addColorStop(1, '#7D4E26');

    // Upper dome cap
    const domeW = glassOuterW * 0.46;
    const domeH = (roofBaseY - roofTopY) * 0.36;
    ctx.beginPath();
    ctx.roundRect(cx - domeW * 0.5, roofTopY, domeW, domeH + minSide * 0.008, [domeH * 0.7, domeH * 0.7, 0, 0]);
    ctx.fillStyle = roofGrad;
    ctx.fill();

    // Sloped main canopy roof
    const eaveW = glassOuterW * 1.18;
    const roofMidY = roofTopY + domeH * 0.85;
    ctx.beginPath();
    ctx.moveTo(cx - domeW * 0.52, roofMidY);
    ctx.lineTo(cx + domeW * 0.52, roofMidY);
    ctx.lineTo(cx + eaveW * 0.5, roofBaseY - minSide * 0.016);
    ctx.lineTo(cx - eaveW * 0.5, roofBaseY - minSide * 0.016);
    ctx.closePath();
    ctx.fillStyle = roofGrad;
    ctx.fill();

    // Eave lip trim
    ctx.beginPath();
    ctx.roundRect(cx - eaveW * 0.52, roofBaseY - minSide * 0.020, eaveW * 1.04, minSide * 0.024, minSide * 0.010);
    ctx.fillStyle = '#D99E5B';
    ctx.fill();

    // 5E. 2-Step Warm Bronze Lantern Pedestal Base
    const baseTopW = glassOuterW * 1.10;
    const baseBotW = glassOuterW * 1.24;
    const baseH = baseBotY - glassBotY;

    const baseGrad = ctx.createLinearGradient(cx - baseBotW * 0.5, glassBotY, cx + baseBotW * 0.5, baseBotY);
    baseGrad.addColorStop(0, '#D99E5B');
    baseGrad.addColorStop(0.5, '#A8703B');
    baseGrad.addColorStop(1, '#6E4521');

    ctx.beginPath();
    ctx.roundRect(cx - baseTopW * 0.5, glassBotY - minSide * 0.004, baseTopW, baseH * 0.48, minSide * 0.010);
    ctx.fillStyle = baseGrad;
    ctx.fill();

    ctx.beginPath();
    ctx.roundRect(cx - baseBotW * 0.5, glassBotY + baseH * 0.36, baseBotW, baseH * 0.64, minSide * 0.014);
    ctx.fillStyle = baseGrad;
    ctx.fill();

    ctx.restore();
  }

  // Seamless Top Anchor Finial Pin (Always present at t=0 and t=20)
  ctx.beginPath();
  ctx.arc(cx, pivotY, minSide * 0.009, 0, Math.PI * 2);
  ctx.fillStyle = '#FFE49E';
  ctx.fill();

  ctx.restore(); // End Pendulum Group
  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.min(sceneCount - 1, Math.floor(loopT / sceneDuration));
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const subP = (p, a, b) => clamp01((p - a) / (b - a));
  const easeInOutCubic = (x) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2);
  const easeOutCubic = (x) => 1 - Math.pow(1 - x, 3);
  const easeInCubic = (x) => x * x * x;

  ctx.save();
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  // 1. Clean Modern Dark Aesthetic Gradient Background (Zero glow effects)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, '#040C14');
  bgGrad.addColorStop(0.52, '#0C2134');
  bgGrad.addColorStop(1, '#03060B');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Timeline Choreography Parameters
  let baseScale = 0.24;
  let domeScale = 0;
  let domeAlpha = 0;
  let tiltDeg = 0;
  let snowAlpha = 0;
  let snowPhase = 0;
  let auroraAlpha = 0;
  let windowWarmth = 0;
  let smokeAlpha = 0;
  let outerAccent = 0;

  if (currentScene === 0) {
    // Scene 1: Pedestal & globe emergence, gentle 1-cycle cradle tilt waking up swirling snow
    baseScale = 0.24 + 0.76 * easeOutCubic(subP(sceneProgress, 0.0, 0.18));
    domeScale = easeOutCubic(subP(sceneProgress, 0.06, 0.34));
    domeAlpha = easeInOutCubic(subP(sceneProgress, 0.06, 0.26));

    const tiltWin = subP(sceneProgress, 0.36, 0.88);
    const tiltEnv = Math.sin(tiltWin * Math.PI);
    tiltDeg = Math.sin(tiltWin * Math.PI * 2) * tiltEnv * 4.5;

    snowAlpha = easeInOutCubic(subP(sceneProgress, 0.42, 0.84));
    snowPhase = subP(sceneProgress, 0.40, 1.0) * 0.45;
  } else if (currentScene === 1) {
    // Scene 2: Waving aurora ribbons in upper sky, warm hearth windows, gentle chimney puffs & snow fall
    baseScale = 1;
    domeScale = 1;
    domeAlpha = 1;
    tiltDeg = 0;

    snowAlpha = 1;
    snowPhase = 0.45 + sceneProgress * 1.15;
    auroraAlpha = easeInOutCubic(subP(sceneProgress, 0.02, 0.28));
    windowWarmth = easeInOutCubic(subP(sceneProgress, 0.10, 0.36));
    smokeAlpha = easeInOutCubic(subP(sceneProgress, 0.16, 0.40));
    outerAccent = easeInOutCubic(subP(sceneProgress, 0.14, 0.38));
  } else {
    // Scene 3: Graceful snow settling, dimming hearth & aurora, clean collapse to base plinth
    outerAccent = 1 - easeInOutCubic(subP(sceneProgress, 0.0, 0.32));
    smokeAlpha = 1 - easeInOutCubic(subP(sceneProgress, 0.0, 0.36));
    windowWarmth = 1 - easeInOutCubic(subP(sceneProgress, 0.08, 0.46));
    auroraAlpha = 1 - easeInOutCubic(subP(sceneProgress, 0.12, 0.50));
    snowAlpha = 1 - easeInOutCubic(subP(sceneProgress, 0.18, 0.62));
    snowPhase = 1.60 + subP(sceneProgress, 0.0, 0.64) * 0.40;

    domeScale = 1 - easeInCubic(subP(sceneProgress, 0.62, 0.92));
    domeAlpha = 1 - easeInOutCubic(subP(sceneProgress, 0.60, 0.88));
    baseScale = 1 - 0.76 * easeInOutCubic(subP(sceneProgress, 0.76, 1.0));
  }

  // 3. Geometric Layout Constants (16:9 centered, strict dome clipping)
  const R = minSide * 0.252;
  const strokeW = minSide * 0.0075;
  const innerR = R - strokeW * 0.55;
  const globeCy = cy - minSide * 0.032;
  const baseTopY = globeCy + R * 0.81;
  const baseBotY = baseTopY + minSide * 0.095;
  const basePivotY = baseBotY;

  // Helper: Draw 4-Point Frost Spark
  function drawSpark(sx, sy, sz, rot, col, alpha) {
    if (sz <= 0.4 || alpha <= 0.01) return;
    ctx.save();
    ctx.translate(sx, sy);
    ctx.rotate(rot);
    ctx.globalAlpha = alpha;
    ctx.beginPath();
    const inner = sz * 0.30;
    for (let i = 0; i < 8; i++) {
      const a = (i * Math.PI) / 4;
      const r = i % 2 === 0 ? sz : inner;
      if (i === 0) ctx.moveTo(Math.cos(a) * r, Math.sin(a) * r);
      else ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r);
    }
    ctx.closePath();
    ctx.fillStyle = col;
    ctx.fill();
    ctx.restore();
  }

  // 4. Exterior Flanking Glacial Sparks (Strictly outside glass dome)
  if (outerAccent > 0.005) {
    const flanks = [
      { x: cx - minSide * 0.34, y: cy - minSide * 0.14, sz: minSide * 0.015, col: '#56E0F5' },
      { x: cx - minSide * 0.37, y: cy + minSide * 0.08, sz: minSide * 0.011, col: '#28E0A8' },
      { x: cx + minSide * 0.34, y: cy - minSide * 0.14, sz: minSide * 0.015, col: '#28E0A8' },
      { x: cx + minSide * 0.37, y: cy + minSide * 0.08, sz: minSide * 0.011, col: '#FFB347' },
    ];
    for (let i = 0; i < flanks.length; i++) {
      const fl = flanks[i];
      const pulse = 0.85 + 0.15 * Math.sin(loopT * Math.PI * 0.9 + i * 1.4);
      drawSpark(fl.x, fl.y, fl.sz * outerAccent * pulse, loopT * 0.5 + i, fl.col, outerAccent * 0.88);
    }
  }

  // 5. Tilted Snow Globe Group (Pivots cleanly around base bottom)
  ctx.save();
  ctx.translate(cx, basePivotY);
  ctx.rotate((tiltDeg * Math.PI) / 180);
  ctx.translate(-cx, -basePivotY);

  // 5A. Crystal Dome Interior (Strictly clipped inside innerR)
  if (domeScale > 0.01 && domeAlpha > 0.01) {
    ctx.save();
    ctx.translate(cx, baseTopY);
    ctx.scale(domeScale, domeScale);
    ctx.translate(-cx, -baseTopY);
    ctx.globalAlpha = domeAlpha;

    ctx.save();
    ctx.beginPath();
    ctx.arc(cx, globeCy, innerR, 0, Math.PI * 2);
    ctx.clip();

    // Layer 1: Deep Arctic Night Dome Sky
    const skyGrad = ctx.createLinearGradient(cx, globeCy - innerR, cx, globeCy + innerR);
    skyGrad.addColorStop(0, '#071728');
    skyGrad.addColorStop(0.65, '#0F2A44');
    skyGrad.addColorStop(1, '#163854');
    ctx.fillStyle = skyGrad;
    ctx.fillRect(cx - innerR, globeCy - innerR, innerR * 2, innerR * 2);

    // Layer 2: Dual Waving Aurora Ribbons (Strictly inside cx ± 0.66*innerR, clear of glass highlight)
    if (auroraAlpha > 0.01) {
      const drawAuroraRibbon = (yBase, amp, thickness, phaseOff, col1, col2, alpha) => {
        ctx.save();
        ctx.globalAlpha = auroraAlpha * alpha;
        const aGrad = ctx.createLinearGradient(cx - innerR * 0.66, yBase, cx + innerR * 0.66, yBase);
        aGrad.addColorStop(0, 'rgba(40, 224, 168, 0.0)');
        aGrad.addColorStop(0.25, col1);
        aGrad.addColorStop(0.75, col2);
        aGrad.addColorStop(1, 'rgba(86, 224, 245, 0.0)');

        const segs = 28;
        ctx.beginPath();
        for (let s = 0; s <= segs; s++) {
          const u = s / segs;
          const px = cx - innerR * 0.66 + u * innerR * 1.32;
          const py = yBase + Math.sin(u * Math.PI * 2.2 + loopT * 0.9 + phaseOff) * amp;
          if (s === 0) ctx.moveTo(px, py);
          else ctx.lineTo(px, py);
        }
        ctx.strokeStyle = aGrad;
        ctx.lineWidth = thickness;
        ctx.stroke();
        ctx.restore();
      };

      drawAuroraRibbon(globeCy - innerR * 0.42, innerR * 0.048, innerR * 0.10, 0.0, '#28E0A8', '#56E0F5', 0.46);
      drawAuroraRibbon(globeCy - innerR * 0.28, innerR * 0.036, innerR * 0.070, 1.8, '#56E0F5', '#28E0A8', 0.34);
    }

    // Layer 3A: Distant Snow Hill Behind Cabin
    ctx.beginPath();
    ctx.moveTo(cx - innerR - 4, globeCy + innerR * 0.46);
    ctx.quadraticCurveTo(cx - innerR * 0.25, globeCy + innerR * 0.32, cx + innerR + 4, globeCy + innerR * 0.48);
    ctx.lineTo(cx + innerR + 4, globeCy + innerR + 4);
    ctx.lineTo(cx - innerR - 4, globeCy + innerR + 4);
    ctx.closePath();
    ctx.fillStyle = '#B8DDF2';
    ctx.fill();

    // Layer 3B: Miniature Stylized Pine Tree on Left Bank (Well separated from cabin)
    const treeX = cx - innerR * 0.34;
    const treeBaseY = globeCy + innerR * 0.56;
    ctx.fillStyle = '#1B5E54';
    const treeTiers = [
      { topY: treeBaseY - innerR * 0.36, botY: treeBaseY - innerR * 0.16, hw: innerR * 0.095 },
      { topY: treeBaseY - innerR * 0.24, botY: treeBaseY, hw: innerR * 0.125 },
    ];
    for (let k = 0; k < treeTiers.length; k++) {
      const tt = treeTiers[k];
      ctx.beginPath();
      ctx.moveTo(treeX, tt.topY);
      ctx.lineTo(treeX + tt.hw, tt.botY);
      ctx.lineTo(treeX - tt.hw, tt.botY);
      ctx.closePath();
      ctx.fill();
    }

    // Layer 3C: Miniature Nordic Cabin on Right-Center Bank
    const cabX = cx + innerR * 0.14;
    const cabW = innerR * 0.44;
    const cabH = innerR * 0.26;
    const cabBaseY = globeCy + innerR * 0.56;
    const cabTopY = cabBaseY - cabH;
    const roofPeakY = cabTopY - innerR * 0.20;

    // Chimney + Rising Smoke Puffs (Strictly inside clean air corridor above chimney)
    const chimX = cabX - cabW * 0.28;
    const chimW = innerR * 0.065;
    const chimTopY = roofPeakY + innerR * 0.03;
    ctx.beginPath();
    ctx.roundRect(chimX - chimW * 0.5, chimTopY, chimW, innerR * 0.16, innerR * 0.015);
    ctx.fillStyle = '#334E6E';
    ctx.fill();

    if (smokeAlpha > 0.01) {
      for (let p = 0; p < 3; p++) {
        const u = ((loopT * 0.28 + p * 0.333) % 1);
        const puffY = chimTopY - innerR * 0.03 - u * (innerR * 0.22);
        const puffX = chimX - Math.sin(u * Math.PI) * (innerR * 0.045);
        const puffR = innerR * (0.018 + u * 0.022);
        const puffFade = Math.sin(u * Math.PI) * smokeAlpha * 0.70;
        if (puffFade > 0.02) {
          ctx.beginPath();
          ctx.arc(puffX, puffY, puffR, 0, Math.PI * 2);
          ctx.fillStyle = `rgba(239, 248, 255, ${puffFade.toFixed(3)})`;
          ctx.fill();
        }
      }
    }

    // Cabin Wall Body
    ctx.beginPath();
    ctx.roundRect(cabX - cabW * 0.5, cabTopY, cabW, cabH + 4, innerR * 0.016);
    ctx.fillStyle = '#263C57';
    ctx.fill();

    // Pitched Roof + Thick Frost Snow Roof Cap
    ctx.beginPath();
    ctx.moveTo(cabX, roofPeakY);
    ctx.lineTo(cabX + cabW * 0.60, cabTopY + innerR * 0.025);
    ctx.lineTo(cabX - cabW * 0.60, cabTopY + innerR * 0.025);
    ctx.closePath();
    ctx.fillStyle = '#18283D';
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(cabX, roofPeakY - innerR * 0.012);
    ctx.lineTo(cabX + cabW * 0.62, cabTopY + innerR * 0.016);
    ctx.strokeStyle = '#EFF8FF';
    ctx.lineWidth = innerR * 0.038;
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(cabX, roofPeakY - innerR * 0.012);
    ctx.lineTo(cabX - cabW * 0.62, cabTopY + innerR * 0.016);
    ctx.stroke();

    // Door (left-center) & Warm Hearth Window (right-center) cleanly separated
    const doorW = cabW * 0.22;
    const doorH = cabH * 0.62;
    const doorX = cabX - cabW * 0.16;
    ctx.beginPath();
    ctx.roundRect(doorX - doorW * 0.5, cabBaseY - doorH, doorW, doorH, [doorW * 0.45, doorW * 0.45, 0, 0]);
    ctx.fillStyle = '#7A4B2A';
    ctx.fill();

    const winSz = cabW * 0.24;
    const winX = cabX + cabW * 0.20;
    const winY = cabBaseY - cabH * 0.52;
    const winColor = windowWarmth > 0.05 ? '#FFB84D' : '#1A2B40';
    ctx.beginPath();
    ctx.roundRect(winX - winSz * 0.5, winY - winSz * 0.5, winSz, winSz, winSz * 0.16);
    ctx.fillStyle = winColor;
    ctx.fill();

    if (windowWarmth > 0.05) {
      ctx.save();
      ctx.globalAlpha = windowWarmth * 0.9;
      ctx.fillStyle = '#FFE89E';
      ctx.beginPath();
      ctx.roundRect(winX - winSz * 0.34, winY - winSz * 0.34, winSz * 0.68, winSz * 0.68, winSz * 0.10);
      ctx.fill();
      ctx.restore();
    }

    // Cross muntin frame on window
    ctx.strokeStyle = '#263C57';
    ctx.lineWidth = Math.max(1.5, innerR * 0.014);
    ctx.beginPath();
    ctx.moveTo(winX, winY - winSz * 0.5);
    ctx.lineTo(winX, winY + winSz * 0.5);
    ctx.moveTo(winX - winSz * 0.5, winY);
    ctx.lineTo(winX + winSz * 0.5, winY);
    ctx.stroke();

    // Layer 3D: Foreground Snow Ground Mound
    const fgGrad = ctx.createLinearGradient(cx, globeCy + innerR * 0.48, cx, globeCy + innerR);
    fgGrad.addColorStop(0, '#EFF8FF');
    fgGrad.addColorStop(1, '#CFE7F7');
    ctx.beginPath();
    ctx.moveTo(cx - innerR - 4, globeCy + innerR * 0.54);
    ctx.quadraticCurveTo(cx + innerR * 0.15, globeCy + innerR * 0.48, cx + innerR + 4, globeCy + innerR * 0.58);
    ctx.lineTo(cx + innerR + 4, globeCy + innerR + 4);
    ctx.lineTo(cx - innerR - 4, globeCy + innerR + 4);
    ctx.closePath();
    ctx.fillStyle = fgGrad;
    ctx.fill();

    // Layer 4: Deterministic Swirling Falling Snow Particles (Strictly clear of ground & rim)
    if (snowAlpha > 0.01) {
      const flakeCount = 18;
      for (let i = 0; i < flakeCount; i++) {
        const seedX = ((i * 37 + 19) % 100) / 100;
        const seedY = ((i * 53 + 7) % 100) / 100;
        const speedMul = 0.75 + (i % 4) * 0.18;
        const u = (seedY + snowPhase * speedMul) % 1;

        const yTop = globeCy - innerR * 0.78;
        const yBot = globeCy + innerR * 0.42;
        const fy = yTop + u * (yBot - yTop);
        const sway = Math.sin(u * Math.PI * 2.5 + i * 1.1) * (innerR * 0.055);
        const fx = cx + (seedX - 0.5) * (innerR * 1.18) + sway;

        const fadeY = subP(u, 0.0, 0.16) * (1 - subP(u, 0.80, 1.0));
        const rad = innerR * (0.013 + (i % 3) * 0.0045);

        ctx.beginPath();
        ctx.arc(fx, fy, rad, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(239, 248, 255, ${(0.88 * snowAlpha * fadeY).toFixed(3)})`;
        ctx.fill();
      }
    }

    // Layer 5: Crisp Specular Glass Highlight Crescent (Upper-left)
    ctx.save();
    ctx.globalAlpha = 0.25;
    ctx.beginPath();
    ctx.arc(cx, globeCy, innerR * 0.875, (-152 * Math.PI) / 180, (-118 * Math.PI) / 180);
    ctx.strokeStyle = '#FFFFFF';
    ctx.lineWidth = innerR * 0.040;
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(cx, globeCy, innerR * 0.875, (-163 * Math.PI) / 180, (-158 * Math.PI) / 180);
    ctx.stroke();
    ctx.restore();

    ctx.restore(); // End Dome Clip

    // Crisp Glass Rim Outline
    ctx.beginPath();
    ctx.arc(cx, globeCy, R, 0, Math.PI * 2);
    ctx.strokeStyle = '#9FE8F7';
    ctx.lineWidth = strokeW;
    ctx.stroke();

    ctx.restore();
  }

  // 5B. Modern 2-Tier Rounded Bronze-Wood Pedestal Base (Uniform proportional scaling)
  ctx.save();
  ctx.translate(cx, baseBotY);
  ctx.scale(baseScale, baseScale);
  ctx.translate(-cx, -baseBotY);

  const curBaseW = minSide * 0.34;
  const curUpperW = curBaseW * 0.88;
  const tierH = (baseBotY - baseTopY) * 0.5;

  const baseGrad = ctx.createLinearGradient(cx - curBaseW * 0.5, baseTopY, cx + curBaseW * 0.5, baseBotY);
  baseGrad.addColorStop(0, '#BA7C4A');
  baseGrad.addColorStop(0.5, '#9A5F33');
  baseGrad.addColorStop(1, '#663B1D');

  // Upper pedestal collar
  ctx.beginPath();
  ctx.roundRect(cx - curUpperW * 0.5, baseTopY, curUpperW, tierH + minSide * 0.008, tierH * 0.42);
  ctx.fillStyle = baseGrad;
  ctx.fill();

  // Lower pedestal plinth
  ctx.beginPath();
  ctx.roundRect(cx - curBaseW * 0.5, baseTopY + tierH * 0.88, curBaseW, tierH * 1.12, tierH * 0.45);
  ctx.fillStyle = baseGrad;
  ctx.fill();

  // Crisp Gold Trim Band on Pedestal
  const bandW = curUpperW * 0.72;
  const bandH = minSide * 0.009;
  ctx.beginPath();
  ctx.roundRect(cx - bandW * 0.5, baseTopY + tierH * 0.42, bandW, bandH, bandH * 0.5);
  ctx.fillStyle = '#FFD166';
  ctx.fill();

  ctx.restore();

  ctx.restore(); // End Tilted Snow Globe Group
  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.min(sceneCount - 1, Math.floor(loopT / sceneDuration));
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const subP = (p, a, b) => clamp01((p - a) / (b - a));
  const easeInOutCubic = (x) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2);
  const easeOutCubic = (x) => 1 - Math.pow(1 - x, 3);
  const easeInCubic = (x) => x * x * x;

  ctx.save();
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  // 1. Clean Modern Dark Aesthetic Gradient Background (Zero glow effects)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, '#051318');
  bgGrad.addColorStop(0.52, '#0C2631');
  bgGrad.addColorStop(1, '#040A0E');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Timeline Choreography Parameters
  let baseScale = 0.22;
  let trunkReveal = 0;
  let tierProgress = [0, 0, 0, 0];
  let garlandReveal = [0, 0, 0, 0];
  let garlandEnergy = 0;
  let starReveal = 0;
  let starBurst = 0;
  let outerAccent = 0;
  let shutdownSweep = 0;

  if (currentScene === 0) {
    // Scene 1: Base & trunk anchor, sequential bottom-to-top foliage tiers, garland arcs & bulbs
    baseScale = 0.22 + 0.78 * easeOutCubic(subP(sceneProgress, 0.0, 0.16));
    trunkReveal = easeOutCubic(subP(sceneProgress, 0.08, 0.26));

    for (let i = 0; i < 4; i++) {
      tierProgress[i] = easeOutCubic(subP(sceneProgress, 0.16 + i * 0.11, 0.44 + i * 0.11));
      garlandReveal[i] = easeInOutCubic(subP(sceneProgress, 0.48 + i * 0.08, 0.72 + i * 0.08));
    }
    starReveal = easeOutCubic(subP(sceneProgress, 0.78, 1.0));
  } else if (currentScene === 1) {
    // Scene 2: Trim-path energy climbs bottom-to-top, igniting ornaments & topper star rays
    baseScale = 1;
    trunkReveal = 1;
    tierProgress = [1, 1, 1, 1];
    garlandReveal = [1, 1, 1, 1];
    starReveal = 1;

    garlandEnergy = easeInOutCubic(subP(sceneProgress, 0.04, 0.58));
    starBurst = easeOutCubic(subP(sceneProgress, 0.48, 0.80));
    outerAccent = easeInOutCubic(subP(sceneProgress, 0.54, 0.86));
  } else {
    // Scene 3: Top-down graceful dimming & reverse orderly fold back to base plinth
    outerAccent = 1 - easeInOutCubic(subP(sceneProgress, 0.0, 0.26));
    starBurst = 1 - easeInOutCubic(subP(sceneProgress, 0.04, 0.30));
    shutdownSweep = easeInOutCubic(subP(sceneProgress, 0.08, 0.42));
    garlandEnergy = 1;

    starReveal = 1 - easeInCubic(subP(sceneProgress, 0.26, 0.48));
    for (let i = 3; i >= 0; i--) {
      const revIdx = 3 - i;
      garlandReveal[i] = 1 - easeInOutCubic(subP(sceneProgress, 0.30 + revIdx * 0.06, 0.52 + revIdx * 0.06));
      tierProgress[i] = 1 - easeInCubic(subP(sceneProgress, 0.44 + revIdx * 0.08, 0.68 + revIdx * 0.08));
    }
    trunkReveal = 1 - easeInCubic(subP(sceneProgress, 0.74, 0.90));
    baseScale = 1 - 0.78 * easeInOutCubic(subP(sceneProgress, 0.80, 1.0));
  }

  // 3. Geometric Tree Layout Constants (16:9 centered with ~19% top & bottom margins)
  const baseBotY = cy + minSide * 0.305;
  const potH = minSide * 0.052;
  const potW = minSide * 0.135;
  const potTopY = baseBotY - potH;
  const trunkW = minSide * 0.048;
  const trunkTopY = cy + minSide * 0.195;

  // 4 Foliage Tiers (Back-to-front: Tier 0 widest bottom -> Tier 3 top apex)
  const tiers = [
    { topY: cy + minSide * 0.025, botY: cy + minSide * 0.228, halfW: minSide * 0.215, colA: '#139A72', colB: '#0A684D', yArcL: cy + minSide * 0.170, yArcR: cy + minSide * 0.184, xSpan: minSide * 0.138, bulbs: 3 },
    { topY: cy - minSide * 0.065, botY: cy + minSide * 0.115, halfW: minSide * 0.172, colA: '#1AB586', colB: '#0E7D5D', yArcL: cy + minSide * 0.064, yArcR: cy + minSide * 0.076, xSpan: minSide * 0.106, bulbs: 3 },
    { topY: cy - minSide * 0.145, botY: cy + minSide * 0.015, halfW: minSide * 0.132, colA: '#24CE9A', colB: '#12946E', yArcL: cy - minSide * 0.020, yArcR: cy - minSide * 0.028, xSpan: minSide * 0.076, bulbs: 2 },
    { topY: cy - minSide * 0.215, botY: cy - minSide * 0.075, halfW: minSide * 0.090, colA: '#32E6AC', colB: '#19AC80', yArcL: cy - minSide * 0.114, yArcR: cy - minSide * 0.114, xSpan: minSide * 0.042, bulbs: 1 },
  ];

  // Helper: Draw Smooth Rounded Isosceles Triangle Tier
  function traceRoundedTriangle(apexX, apexY, botY, halfW, r) {
    const xL = apexX - halfW;
    const xR = apexX + halfW;
    ctx.beginPath();
    ctx.moveTo(apexX - r * 0.45, apexY + r * 0.75);
    ctx.quadraticCurveTo(apexX, apexY, apexX + r * 0.45, apexY + r * 0.75);
    ctx.lineTo(xR - r * 0.65, botY - r * 0.9);
    ctx.quadraticCurveTo(xR, botY, xR - r, botY);
    ctx.lineTo(xL + r, botY);
    ctx.quadraticCurveTo(xL, botY, xL + r * 0.65, botY - r * 0.9);
    ctx.closePath();
  }

  // Helper: Draw 4-Point Crisp Gold Star
  function drawStar(sx, sy, rad, rot, col, alpha) {
    if (rad <= 0.4 || alpha <= 0.01) return;
    ctx.save();
    ctx.translate(sx, sy);
    ctx.rotate(rot);
    ctx.globalAlpha = alpha;
    ctx.beginPath();
    const inner = rad * 0.36;
    for (let i = 0; i < 8; i++) {
      const a = (i * Math.PI) / 4;
      const r = i % 2 === 0 ? rad : inner;
      if (i === 0) ctx.moveTo(Math.cos(a) * r, Math.sin(a) * r);
      else ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r);
    }
    ctx.closePath();
    ctx.fillStyle = col;
    ctx.fill();
    ctx.restore();
  }

  // 4. Exterior Flanking Glacial & Amber Diamond Accents (Strictly outside tree silhouette)
  if (outerAccent > 0.005) {
    const flanks = [
      { x: cx - minSide * 0.32, y: cy - minSide * 0.12, sz: minSide * 0.015, col: '#6CE5FF' },
      { x: cx - minSide * 0.35, y: cy + minSide * 0.10, sz: minSide * 0.012, col: '#FFD166' },
      { x: cx + minSide * 0.32, y: cy - minSide * 0.12, sz: minSide * 0.015, col: '#FFD166' },
      { x: cx + minSide * 0.35, y: cy + minSide * 0.10, sz: minSide * 0.012, col: '#2CE5A7' },
    ];
    for (let i = 0; i < flanks.length; i++) {
      const fl = flanks[i];
      const pulse = 0.85 + 0.15 * Math.sin(loopT * Math.PI * 0.9 + i * 1.4);
      drawStar(fl.x, fl.y, fl.sz * outerAccent * pulse, loopT * 0.5 + i, fl.col, outerAccent * 0.88);
    }
  }

  // 5. Sleek Modern Pedestal Base & Trunk
  const curPotW = potW * baseScale;
  const curPotH = potH * (0.28 + 0.72 * baseScale);
  const curPotTop = baseBotY - curPotH;

  if (trunkReveal > 0.01) {
    const trH = (potTopY - trunkTopY) * trunkReveal;
    ctx.beginPath();
    ctx.roundRect(cx - trunkW * 0.5, potTopY - trH, trunkW, trH + 4, trunkW * 0.18);
    ctx.fillStyle = '#8A5736';
    ctx.fill();
  }

  // Trapezoid modern geometric pot
  ctx.save();
  ctx.beginPath();
  ctx.roundRect(cx - curPotW * 0.5, curPotTop, curPotW, curPotH, curPotH * 0.28);
  const potGrad = ctx.createLinearGradient(cx - curPotW * 0.5, curPotTop, cx + curPotW * 0.5, baseBotY);
  potGrad.addColorStop(0, '#FFE08A');
  potGrad.addColorStop(0.55, '#D99B38');
  potGrad.addColorStop(1, '#9E681B');
  ctx.fillStyle = potGrad;
  ctx.fill();
  ctx.restore();

  // 6. 4 Layered Foliage Tiers with Clipped Circuit Garland Arcs & Non-Overlapping Jewel Bulbs
  for (let i = 0; i < tiers.length; i++) {
    const tr = tiers[i];
    const tp = tierProgress[i];
    if (tp <= 0.01) continue;

    // Subtle soft drop shadow cast on tier immediately beneath (drawn just before upper tier)
    if (i > 0 && tierProgress[i - 1] > 0.5) {
      ctx.save();
      ctx.globalAlpha = 0.22 * tp;
      traceRoundedTriangle(cx, tr.topY + minSide * 0.012, tr.botY + minSide * 0.012, tr.halfW * tp, minSide * 0.018);
      ctx.fillStyle = '#031912';
      ctx.fill();
      ctx.restore();
    }

    ctx.save();
    const curBotY = tr.botY;
    const curTopY = tr.botY - (tr.botY - tr.topY) * tp;
    const curHalfW = tr.halfW * tp;

    traceRoundedTriangle(cx, curTopY, curBotY, curHalfW, minSide * 0.020);
    const tierGrad = ctx.createLinearGradient(cx - curHalfW, curTopY, cx + curHalfW, curBotY);
    tierGrad.addColorStop(0, tr.colA);
    tierGrad.addColorStop(1, tr.colB);
    ctx.fillStyle = tierGrad;
    ctx.fill();

    // Clip garland curve & ornament sockets cleanly inside this tier
    const gRev = garlandReveal[i];
    if (gRev > 0.01 && tp > 0.85) {
      ctx.save();
      ctx.clip();

      const p0x = cx - tr.xSpan;
      const p0y = tr.yArcL;
      const p2x = cx + tr.xSpan;
      const p2y = tr.yArcR;
      const ctrlX = cx;
      const ctrlY = (p0y + p2y) * 0.5 + minSide * (i === 3 ? 0.016 : 0.024);

      const evalQuad = (u) => {
        const inv = 1 - u;
        return {
          x: inv * inv * p0x + 2 * inv * u * ctrlX + u * u * p2x,
          y: inv * inv * p0y + 2 * inv * u * ctrlY + u * u * p2y,
        };
      };

      // Base subtle circuit trace line
      const segs = 24;
      ctx.beginPath();
      for (let s = 0; s <= segs; s++) {
        const u = (s / segs) * gRev;
        const pt = evalQuad(u);
        if (s === 0) ctx.moveTo(pt.x, pt.y);
        else ctx.lineTo(pt.x, pt.y);
      }
      ctx.strokeStyle = 'rgba(255, 232, 168, 0.34)';
      ctx.lineWidth = minSide * 0.0046;
      ctx.stroke();

      // Energized trim-path sweep along tier garland
      const tierWinStart = i * 0.22;
      const tierWinEnd = tierWinStart + 0.34;
      const upEnergy = easeInOutCubic(subP(garlandEnergy, tierWinStart, tierWinEnd));
      const downOff = shutdownSweep > 0 ? easeInOutCubic(subP(shutdownSweep, (3 - i) * 0.20, (3 - i) * 0.20 + 0.32)) : 0;
      const activeLevel = clamp01(upEnergy * (1 - downOff));

      if (activeLevel > 0.01) {
        ctx.beginPath();
        for (let s = 0; s <= segs; s++) {
          const u = (s / segs) * Math.min(gRev, activeLevel);
          const pt = evalQuad(u);
          if (s === 0) ctx.moveTo(pt.x, pt.y);
          else ctx.lineTo(pt.x, pt.y);
        }
        ctx.strokeStyle = '#FFE499';
        ctx.lineWidth = minSide * 0.0052;
        ctx.stroke();
      }

      // Crisp Jewel Ornament Bulbs seated directly on garland nodes (zero intersecting lines)
      for (let b = 0; b < tr.bulbs; b++) {
        const uNode = tr.bulbs === 1 ? 0.5 : tr.bulbs === 2 ? 0.28 + b * 0.44 : 0.16 + b * 0.34;
        if (gRev < uNode) continue;
        const pop = easeOutCubic(subP(gRev, uNode, Math.min(1, uNode + 0.18)));
        const pt = evalQuad(uNode);
        const lit = activeLevel >= uNode ? easeOutCubic(subP(activeLevel, uNode, Math.min(1, uNode + 0.12))) : 0;

        const baseColors = ['#FF5D6C', '#6CE5FF', '#FFD166'];
        const bulbCol = baseColors[(i + b) % baseColors.length];
        const bulbR = minSide * 0.014 * pop * (1 + 0.16 * lit);

        ctx.beginPath();
        ctx.arc(pt.x, pt.y, bulbR, 0, Math.PI * 2);
        ctx.fillStyle = lit > 0.4 ? '#FFF2C2' : bulbCol;
        ctx.fill();

        ctx.beginPath();
        ctx.arc(pt.x, pt.y, bulbR * 0.62, 0, Math.PI * 2);
        ctx.fillStyle = bulbCol;
        ctx.fill();

        if (lit > 0.2) {
          ctx.beginPath();
          ctx.arc(pt.x - bulbR * 0.24, pt.y - bulbR * 0.24, bulbR * 0.22 * lit, 0, Math.PI * 2);
          ctx.fillStyle = '#FFFFFF';
          ctx.fill();
        }
      }

      ctx.restore();
    }

    ctx.restore();
  }

  // 7. Topper Star & Short Clean Radial Star-Burst Rays (Strictly above Tier 3 apex)
  const starY = cy - minSide * 0.278;
  if (starReveal > 0.01) {
    // 7 short radial burst ticks strictly in upper 210-degree arc (never pointing down into tree apex)
    if (starBurst > 0.01) {
      const rayAnglesDeg = [-195, -160, -125, -90, -55, -20, 15];
      const rIn = minSide * 0.056;
      const rLen = minSide * 0.028 * starBurst;
      ctx.save();
      ctx.translate(cx, starY);
      for (let k = 0; k < rayAnglesDeg.length; k++) {
        const a = (rayAnglesDeg[k] * Math.PI) / 180;
        const pulse = 0.85 + 0.15 * Math.sin(loopT * Math.PI * 1.1 + k * 0.9);
        ctx.beginPath();
        ctx.moveTo(Math.cos(a) * rIn, Math.sin(a) * rIn);
        ctx.lineTo(Math.cos(a) * (rIn + rLen * pulse), Math.sin(a) * (rIn + rLen * pulse));
        ctx.strokeStyle = k % 2 === 0 ? '#FFE89E' : '#6CE5FF';
        ctx.globalAlpha = 0.86 * starBurst;
        ctx.lineWidth = minSide * 0.0040;
        ctx.stroke();
      }
      ctx.restore();
    }

    // Crisp 2-tone Gold Topper Star
    const starScale = starReveal * (1 + 0.08 * starBurst);
    drawStar(cx, starY, minSide * 0.044 * starScale, 0, '#FFD166', starReveal);
    drawStar(cx, starY, minSide * 0.024 * starScale, Math.PI / 4, '#FFF6D6', starReveal);
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.min(sceneCount - 1, Math.floor(loopT / sceneDuration));
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const subP = (p, a, b) => clamp01((p - a) / (b - a));
  const easeInOutCubic = (x) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2);
  const easeOutCubic = (x) => 1 - Math.pow(1 - x, 3);
  const easeInCubic = (x) => x * x * x;

  ctx.save();
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  // 1. Clean Modern Dark Aesthetic Gradient Background (Zero glow effects)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, '#11071B');
  bgGrad.addColorStop(0.52, '#240F38');
  bgGrad.addColorStop(1, '#090410');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Timeline Choreography Parameters
  let boxScale = 0.16;
  let boxAlpha = 1;
  let bowOpen = 0;
  let lidLift = 0;
  let iconFan = 0;
  let rayAlpha = 0;
  let hoverTime = 0;
  let outerAccent = 0;

  if (currentScene === 0) {
    // Scene 1: Poised gift box reveal, bow unfold, smooth vertical lid lift, diverging icon fan-out
    boxScale = 0.16 + 0.84 * easeOutCubic(subP(sceneProgress, 0.0, 0.22));
    bowOpen = easeInOutCubic(subP(sceneProgress, 0.22, 0.40));
    lidLift = easeInOutCubic(subP(sceneProgress, 0.34, 0.66));
    iconFan = easeOutCubic(subP(sceneProgress, 0.52, 0.96));
    rayAlpha = easeInOutCubic(subP(sceneProgress, 0.50, 0.86));
    outerAccent = easeInOutCubic(subP(sceneProgress, 0.72, 1.0));
    hoverTime = 0;
  } else if (currentScene === 1) {
    // Scene 2: Harmonious showcase hover, gentle icon spin, radiant vector rays, flanking accents
    boxScale = 1;
    bowOpen = 1;
    lidLift = 1;
    iconFan = 1;
    rayAlpha = 1;
    outerAccent = 1;
    hoverTime = sceneProgress;
  } else {
    // Scene 3: Smooth reverse magnetic retraction into box, lid close, bow fasten, seamless reset
    outerAccent = 1 - easeInOutCubic(subP(sceneProgress, 0.0, 0.28));
    rayAlpha = 1 - easeInOutCubic(subP(sceneProgress, 0.08, 0.42));
    iconFan = 1 - easeInCubic(subP(sceneProgress, 0.06, 0.48));
    lidLift = 1 - easeInOutCubic(subP(sceneProgress, 0.38, 0.70));
    bowOpen = 1 - easeInOutCubic(subP(sceneProgress, 0.64, 0.82));
    boxScale = 1 - 0.84 * easeInCubic(subP(sceneProgress, 0.76, 1.0));
    hoverTime = 0;
  }

  // 3. Geometric Layout Constants (Strictly verified clearance corridors)
  const boxW = minSide * 0.30;
  const boxH = minSide * 0.20;
  const boxBottom = cy + minSide * 0.275;
  const boxTop = boxBottom - boxH;

  const lidW = minSide * 0.332;
  const lidH = minSide * 0.056;
  const closedLidTop = boxTop - lidH + minSide * 0.004;
  const liftDist = minSide * 0.285;
  const hoverLidOffset = Math.sin(hoverTime * Math.PI * 2) * (minSide * 0.006);
  const currentLidTop = closedLidTop - lidLift * liftDist + hoverLidOffset;
  const currentLidBot = currentLidTop + lidH;

  // Helper: Draw 4-Point Crisp Gold Star
  function drawStar4(sx, sy, rad, rot, col, alpha) {
    if (rad <= 0.4 || alpha <= 0.01) return;
    ctx.save();
    ctx.translate(sx, sy);
    ctx.rotate(rot);
    ctx.globalAlpha = alpha;
    ctx.beginPath();
    const inner = rad * 0.36;
    for (let i = 0; i < 8; i++) {
      const a = (i * Math.PI) / 4;
      const r = i % 2 === 0 ? rad : inner;
      if (i === 0) ctx.moveTo(Math.cos(a) * r, Math.sin(a) * r);
      else ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r);
    }
    ctx.closePath();
    ctx.fillStyle = col;
    ctx.fill();
    ctx.restore();
  }

  // Helper: Draw 6-Point Geometric Vector Snowflake
  function drawSnowflake(sx, sy, rad, rot, col, alpha) {
    if (rad <= 0.4 || alpha <= 0.01) return;
    ctx.save();
    ctx.translate(sx, sy);
    ctx.rotate(rot);
    ctx.globalAlpha = alpha;
    ctx.strokeStyle = col;
    ctx.lineWidth = Math.max(1.5, rad * 0.14);

    for (let i = 0; i < 3; i++) {
      const a = (i * Math.PI) / 3;
      const dx = Math.cos(a) * rad;
      const dy = Math.sin(a) * rad;
      ctx.beginPath();
      ctx.moveTo(-dx, -dy);
      ctx.lineTo(dx, dy);
      ctx.stroke();

      // Clean chevron tips at both ends
      for (let dir = -1; dir <= 1; dir += 2) {
        const bx = dir * Math.cos(a) * rad * 0.62;
        const by = dir * Math.sin(a) * rad * 0.62;
        const branchLen = rad * 0.30;
        for (let b = -1; b <= 1; b += 2) {
          const ba = a + (dir < 0 ? Math.PI : 0) + b * (Math.PI / 4);
          ctx.beginPath();
          ctx.moveTo(bx, by);
          ctx.lineTo(bx + Math.cos(ba) * branchLen, by + Math.sin(ba) * branchLen);
          ctx.stroke();
        }
      }
    }
    ctx.beginPath();
    ctx.arc(0, 0, rad * 0.18, 0, Math.PI * 2);
    ctx.fillStyle = col;
    ctx.fill();
    ctx.restore();
  }

  // Helper: Draw Mini Christmas Ornament Bauble Icon
  function drawMiniBauble(bx, by, rad, colMain, colLight, alpha) {
    if (rad <= 0.4 || alpha <= 0.01) return;
    ctx.save();
    ctx.translate(bx, by);
    ctx.globalAlpha = alpha;

    // Gold cap & ring
    ctx.beginPath();
    ctx.arc(0, -rad * 0.96, rad * 0.22, 0, Math.PI * 2);
    ctx.strokeStyle = '#FFD166';
    ctx.lineWidth = Math.max(1.5, rad * 0.12);
    ctx.stroke();

    ctx.beginPath();
    ctx.roundRect(-rad * 0.24, -rad * 0.82, rad * 0.48, rad * 0.26, rad * 0.08);
    ctx.fillStyle = '#FFD166';
    ctx.fill();

    // Bauble body
    const bGrad = ctx.createLinearGradient(-rad * 0.6, -rad * 0.6, rad * 0.6, rad * 0.7);
    bGrad.addColorStop(0, colLight);
    bGrad.addColorStop(1, colMain);
    ctx.beginPath();
    ctx.arc(0, rad * 0.12, rad * 0.74, 0, Math.PI * 2);
    ctx.fillStyle = bGrad;
    ctx.fill();

    // Clean horizontal accent band inside bauble
    ctx.save();
    ctx.clip();
    ctx.fillStyle = '#FFE8B8';
    ctx.fillRect(-rad, rad * 0.04, rad * 2, rad * 0.16);
    ctx.restore();

    ctx.restore();
  }

  // Helper: Draw Mini Faceted Crystal Diamond Icon
  function drawMiniDiamond(dx, dy, rad, colTop, colBot, alpha) {
    if (rad <= 0.4 || alpha <= 0.01) return;
    ctx.save();
    ctx.translate(dx, dy);
    ctx.globalAlpha = alpha;

    ctx.beginPath();
    ctx.moveTo(0, -rad);
    ctx.lineTo(rad * 0.78, 0);
    ctx.lineTo(0, rad);
    ctx.lineTo(-rad * 0.78, 0);
    ctx.closePath();
    ctx.fillStyle = colBot;
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(0, -rad);
    ctx.lineTo(rad * 0.78, 0);
    ctx.lineTo(-rad * 0.78, 0);
    ctx.closePath();
    ctx.fillStyle = colTop;
    ctx.fill();

    ctx.restore();
  }

  // Helper: Draw Mini Stylized Festive Tree Badge Icon
  function drawMiniTreeBadge(tx, ty, rad, alpha) {
    if (rad <= 0.4 || alpha <= 0.01) return;
    ctx.save();
    ctx.translate(tx, ty);
    ctx.globalAlpha = alpha;

    // Trunk
    ctx.beginPath();
    ctx.roundRect(-rad * 0.14, rad * 0.42, rad * 0.28, rad * 0.36, rad * 0.05);
    ctx.fillStyle = '#FFD166';
    ctx.fill();

    // Upper & lower rounded triangle tiers
    const tiers = [
      { topY: -rad * 0.82, botY: -rad * 0.08, halfW: rad * 0.56, col: '#2ED8B6' },
      { topY: -rad * 0.36, botY: rad * 0.46, halfW: rad * 0.78, col: '#1FB294' },
    ];
    for (let i = tiers.length - 1; i >= 0; i--) {
      const tr = tiers[i];
      ctx.beginPath();
      ctx.moveTo(0, tr.topY);
      ctx.lineTo(tr.halfW, tr.botY);
      ctx.lineTo(-tr.halfW, tr.botY);
      ctx.closePath();
      ctx.fillStyle = tr.col;
      ctx.fill();
    }

    ctx.restore();
  }

  // 4. Exterior Flanking Geometric Sparks (Strictly outside fan & box corridor)
  if (outerAccent > 0.005) {
    const flanks = [
      { x: cx - minSide * 0.38, y: cy - minSide * 0.12, sz: minSide * 0.015, col: '#2ED8B6' },
      { x: cx - minSide * 0.36, y: cy + minSide * 0.14, sz: minSide * 0.012, col: '#FFD166' },
      { x: cx + minSide * 0.38, y: cy - minSide * 0.12, sz: minSide * 0.015, col: '#FF5D7E' },
      { x: cx + minSide * 0.36, y: cy + minSide * 0.14, sz: minSide * 0.012, col: '#2ED8B6' },
    ];
    for (let i = 0; i < flanks.length; i++) {
      const fl = flanks[i];
      const pulse = 0.85 + 0.15 * Math.sin(loopT * Math.PI * 0.9 + i * 1.5);
      drawStar4(fl.x, fl.y, fl.sz * outerAccent * pulse, loopT * 0.6 + i, fl.col, outerAccent * 0.88);
    }
  }

  // 5. Scaled Gift Box Root (Scales from bottom center for clean t=0 / t=20 seamless anchor)
  ctx.save();
  ctx.translate(cx, boxBottom);
  ctx.scale(boxScale, boxScale);
  ctx.translate(-cx, -boxBottom);
  ctx.globalAlpha = boxAlpha;

  // 5A. Crisp Vector Light Rays Inside Open Showcase Corridor (Short & angled cleanly BETWEEN icons)
  if (rayAlpha > 0.005 && lidLift > 0.25) {
    const rayAngles = [-46, -16, 16, 46];
    const originY = boxTop - minSide * 0.012;
    for (let i = 0; i < rayAngles.length; i++) {
      const ang = ((rayAngles[i] - 90) * Math.PI) / 180;
      const rStart = minSide * 0.018;
      const rMaxLen = minSide * 0.068 * lidLift * rayAlpha;
      const rEnd = rStart + rMaxLen;
      ctx.save();
      ctx.globalAlpha = 0.42 * rayAlpha;
      ctx.strokeStyle = i % 2 === 0 ? '#FFD166' : '#2ED8B6';
      ctx.lineWidth = minSide * 0.0044;
      ctx.beginPath();
      ctx.moveTo(cx + Math.cos(ang) * rStart, originY + Math.sin(ang) * rStart);
      ctx.lineTo(cx + Math.cos(ang) * rEnd, originY + Math.sin(ang) * rEnd);
      ctx.stroke();
      ctx.restore();
    }
  }

  // 5B. Back Interior Opening Rim (Reveals cleanly when lid lifts)
  if (lidLift > 0.02) {
    ctx.save();
    ctx.globalAlpha = lidLift;
    ctx.beginPath();
    ctx.roundRect(cx - boxW * 0.47, boxTop - minSide * 0.010, boxW * 0.94, minSide * 0.028, minSide * 0.010);
    ctx.fillStyle = '#380E27';
    ctx.fill();
    ctx.restore();
  }

  // 5C. 5 Emerging Christmas Surprise Mini-Icons (Clipped cleanly above boxTop, clear of lid)
  if (iconFan > 0.005) {
    ctx.save();
    ctx.beginPath();
    ctx.rect(cx - minSide * 0.46, cy - minSide * 0.46, minSide * 0.92, boxTop - (cy - minSide * 0.46) + minSide * 0.004);
    ctx.clip();

    const originX = cx;
    const originY = boxTop + minSide * 0.015;

    // 5 strictly non-overlapping showcase target positions between boxTop (cy+0.075) & open lidBot (cy-0.210)
    const targets = [
      { id: 'star', x: cx, y: cy - minSide * 0.118, r: minSide * 0.044, phase: 0.0 },
      { id: 'bauble', x: cx - minSide * 0.138, y: cy - minSide * 0.084, r: minSide * 0.037, phase: 1.2 },
      { id: 'diamond', x: cx + minSide * 0.138, y: cy - minSide * 0.084, r: minSide * 0.037, phase: 2.4 },
      { id: 'snow', x: cx - minSide * 0.258, y: cy - minSide * 0.028, r: minSide * 0.038, phase: 3.6 },
      { id: 'tree', x: cx + minSide * 0.258, y: cy - minSide * 0.028, r: minSide * 0.040, phase: 4.8 },
    ];

    for (let i = 0; i < targets.length; i++) {
      const tg = targets[i];
      const hoverY = Math.sin(hoverTime * Math.PI * 2 + tg.phase) * (minSide * 0.008) * iconFan;
      const px = originX + (tg.x - originX) * iconFan;
      const py = originY + (tg.y - originY) * iconFan + hoverY;
      const curR = tg.r * iconFan;
      const curAlpha = clamp01(iconFan * 1.4);

      if (tg.id === 'star') {
        drawStar4(px, py, curR, hoverTime * Math.PI * 0.5, '#FFD166', curAlpha);
      } else if (tg.id === 'bauble') {
        drawMiniBauble(px, py, curR, '#1CA88B', '#4AE6C5', curAlpha);
      } else if (tg.id === 'diamond') {
        drawMiniDiamond(px, py, curR, '#FF8FA8', '#FF4D6D', curAlpha);
      } else if (tg.id === 'snow') {
        drawSnowflake(px, py, curR, hoverTime * Math.PI * 0.5, '#EFE5FF', curAlpha);
      } else {
        drawMiniTreeBadge(px, py, curR, curAlpha);
      }
    }

    ctx.restore();
  }

  // 5D. Gift Box Lower Base Body + Vertical Gold Ribbon
  const boxGrad = ctx.createLinearGradient(cx - boxW * 0.5, boxTop, cx + boxW * 0.5, boxBottom);
  boxGrad.addColorStop(0, '#FF4D6D');
  boxGrad.addColorStop(0.55, '#E22F52');
  boxGrad.addColorStop(1, '#B3193B');

  ctx.beginPath();
  ctx.roundRect(cx - boxW * 0.5, boxTop, boxW, boxH, minSide * 0.018);
  ctx.fillStyle = boxGrad;
  ctx.fill();

  // Subtle top lip shading right under lid edge
  ctx.fillStyle = 'rgba(28, 8, 22, 0.22)';
  ctx.fillRect(cx - boxW * 0.5, boxTop, boxW, minSide * 0.018);

  // Clean Vertical Luminous Gold Ribbon Band on Box Front
  const ribW = minSide * 0.052;
  const ribGrad = ctx.createLinearGradient(cx - ribW * 0.5, boxTop, cx + ribW * 0.5, boxBottom);
  ribGrad.addColorStop(0, '#FFE499');
  ribGrad.addColorStop(0.5, '#FFD166');
  ribGrad.addColorStop(1, '#E5A232');

  ctx.save();
  ctx.beginPath();
  ctx.roundRect(cx - boxW * 0.5, boxTop, boxW, boxH, minSide * 0.018);
  ctx.clip();
  ctx.fillStyle = ribGrad;
  ctx.fillRect(cx - ribW * 0.5, boxTop, ribW, boxH);
  ctx.restore();

  // 5E. Levitating Gift Box Lid + Double-Loop Gold Ribbon Bow
  ctx.save();

  const lidGrad = ctx.createLinearGradient(cx - lidW * 0.5, currentLidTop, cx + lidW * 0.5, currentLidBot);
  lidGrad.addColorStop(0, '#FF6884');
  lidGrad.addColorStop(0.55, '#EA385C');
  lidGrad.addColorStop(1, '#BD1D40');

  ctx.beginPath();
  ctx.roundRect(cx - lidW * 0.5, currentLidTop, lidW, lidH, minSide * 0.015);
  ctx.fillStyle = lidGrad;
  ctx.fill();

  // Gold ribbon crossband on lid
  ctx.save();
  ctx.clip();
  ctx.fillStyle = ribGrad;
  ctx.fillRect(cx - ribW * 0.5, currentLidTop, ribW, lidH);
  ctx.restore();

  // Double-Loop Gold Ribbon Bow resting cleanly on lid top
  const bowAnchorY = currentLidTop;
  const loopSpread = minSide * (0.068 + 0.016 * bowOpen);
  const loopHeight = minSide * (0.044 + 0.008 * bowOpen);

  for (let side = -1; side <= 1; side += 2) {
    ctx.beginPath();
    ctx.moveTo(cx, bowAnchorY - minSide * 0.004);
    ctx.bezierCurveTo(
      cx + side * loopSpread * 0.45,
      bowAnchorY - loopHeight * 1.15,
      cx + side * loopSpread * 1.12,
      bowAnchorY - loopHeight * 0.85,
      cx + side * loopSpread,
      bowAnchorY - minSide * 0.006
    );
    ctx.bezierCurveTo(
      cx + side * loopSpread * 0.85,
      bowAnchorY + minSide * 0.004,
      cx + side * loopSpread * 0.30,
      bowAnchorY,
      cx,
      bowAnchorY
    );
    ctx.closePath();

    const bowLoopGrad = ctx.createLinearGradient(cx, bowAnchorY - loopHeight, cx + side * loopSpread, bowAnchorY);
    bowLoopGrad.addColorStop(0, '#FFE8A8');
    bowLoopGrad.addColorStop(1, '#E5A232');
    ctx.fillStyle = bowLoopGrad;
    ctx.fill();
  }

  // Center bow knot cap
  const knotW = minSide * 0.032;
  const knotH = minSide * 0.022;
  ctx.beginPath();
  ctx.roundRect(cx - knotW * 0.5, bowAnchorY - knotH * 0.85, knotW, knotH, knotH * 0.35);
  ctx.fillStyle = '#FFF0BE';
  ctx.fill();

  ctx.restore(); // End Lid & Bow
  ctx.restore(); // End Gift Box Root

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.min(sceneCount - 1, Math.floor(loopT / sceneDuration));
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const subP = (p, a, b) => clamp01((p - a) / (b - a));
  const easeInOutCubic = (x) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2);
  const easeOutCubic = (x) => 1 - Math.pow(1 - x, 3);
  const easeInCubic = (x) => x * x * x;
  const easeInOutSine = (x) => -(Math.cos(Math.PI * x) - 1) / 2;

  ctx.save();
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  // 1. Clean Modern Dark Aesthetic Gradient Background (Zero glow effects)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, '#04140F');
  bgGrad.addColorStop(0.52, '#0B2920');
  bgGrad.addColorStop(1, '#030A07');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Timeline Choreography Parameters
  let seedAlpha = 1;
  let bowScale = 0;
  let ribbonReveal = 0;
  let bellScale = 0;
  let bellAlpha = 0;
  let baseSpreadDeg = 22;
  let swingDeg = 0;
  let clapperDeg = 0;
  let wavePhase = 0;
  let waveAlpha = 0;
  let chimeAlpha = 0;
  let ribbonFlutterPhase = 0;

  if (currentScene === 0) {
    // Scene 1: Bow & yoke emergence, ribbon tail extension, symmetrical bell reveal
    bowScale = easeOutCubic(subP(sceneProgress, 0.02, 0.30));
    ribbonReveal = easeInOutCubic(subP(sceneProgress, 0.20, 0.62));
    bellScale = easeOutCubic(subP(sceneProgress, 0.34, 0.72));
    bellAlpha = easeInOutCubic(subP(sceneProgress, 0.34, 0.54));

    const openSwing = easeInOutCubic(subP(sceneProgress, 0.68, 1.0));
    baseSpreadDeg = 22 + 5 * openSwing;
    ribbonFlutterPhase = loopT * 2.2;
  } else if (currentScene === 1) {
    // Scene 2: Synchronized harmonic bell ringing, clapper momentum, outer acoustic wave arcs
    bowScale = 1;
    ribbonReveal = 1;
    bellScale = 1;
    bellAlpha = 1;

    baseSpreadDeg = 27;
    const bellCycle = Math.sin(sceneProgress * Math.PI * 4);
    const bellEnv = easeInOutSine(subP(sceneProgress, 0.0, 0.16)) * (1 - easeInOutSine(subP(sceneProgress, 0.84, 1.0)));
    swingDeg = bellCycle * 6.5 * (0.35 + 0.65 * bellEnv);
    clapperDeg = Math.sin(sceneProgress * Math.PI * 4 - 0.55) * 8.5 * (0.35 + 0.65 * bellEnv);

    waveAlpha = easeInOutCubic(subP(sceneProgress, 0.08, 0.24)) * (1 - easeInOutCubic(subP(sceneProgress, 0.82, 0.98)));
    wavePhase = (sceneProgress * 3) % 1;
    chimeAlpha = waveAlpha;
    ribbonFlutterPhase = loopT * 2.2;
  } else {
    // Scene 3: Graceful deceleration, ribbon retraction, clean seamless collapse to bow anchor
    const settleP = easeOutCubic(subP(sceneProgress, 0.0, 0.30));
    baseSpreadDeg = 27 - 5 * settleP;
    swingDeg = 0;
    clapperDeg = 0;

    bellScale = 1 - easeInCubic(subP(sceneProgress, 0.30, 0.68));
    bellAlpha = 1 - easeInOutCubic(subP(sceneProgress, 0.42, 0.68));
    ribbonReveal = 1 - easeInOutCubic(subP(sceneProgress, 0.46, 0.82));
    bowScale = 1 - easeInCubic(subP(sceneProgress, 0.72, 0.98));
    ribbonFlutterPhase = loopT * 2.2;
  }

  // 3. Geometric Layout Constants (Guaranteed non-overlapping zones)
  const pivotY = cy - minSide * 0.075;
  const pivotSepX = minSide * 0.088;
  const leftPivotX = cx - pivotSepX;
  const rightPivotX = cx + pivotSepX;

  const bellH = minSide * 0.265;
  const rimHalfW = minSide * 0.112;
  const domeHalfW = minSide * 0.058;

  // Helper: Draw Crisp 4-Point Champagne Chime Spark
  function drawSpark(sx, sy, sz, rot, col, alpha) {
    if (sz <= 0.4 || alpha <= 0.01) return;
    ctx.save();
    ctx.translate(sx, sy);
    ctx.rotate(rot);
    ctx.globalAlpha = alpha;
    ctx.beginPath();
    const inner = sz * 0.30;
    for (let i = 0; i < 8; i++) {
      const a = (i * Math.PI) / 4;
      const r = i % 2 === 0 ? sz : inner;
      if (i === 0) ctx.moveTo(Math.cos(a) * r, Math.sin(a) * r);
      else ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r);
    }
    ctx.closePath();
    ctx.fillStyle = col;
    ctx.fill();
    ctx.restore();
  }

  // Helper: Draw One Burnished Rose-Gold Bell around its top pivot (0, 0)
  function drawBell(px, py, bellAngleDeg, clapDeg, scale, alpha) {
    if (scale <= 0.01 || alpha <= 0.01) return;
    ctx.save();
    ctx.translate(px, py);
    ctx.scale(scale, scale);
    ctx.rotate((bellAngleDeg * Math.PI) / 180);
    ctx.globalAlpha = alpha;

    // Top mounting loop
    ctx.beginPath();
    ctx.arc(0, 0, minSide * 0.016, 0, Math.PI * 2);
    ctx.strokeStyle = '#F7C99B';
    ctx.lineWidth = minSide * 0.006;
    ctx.stroke();

    // Inner dark mouth cavity & swinging Rose-Gold Clapper (peeks cleanly below rim lip)
    const rimY = bellH;
    const clapperLen = bellH * 1.03;
    const clapRad = (clapDeg * Math.PI) / 180;
    const clapX = -Math.sin(clapRad) * clapperLen;
    const clapY = Math.cos(clapRad) * clapperLen;

    // Clapper stem & sphere (drawn before bell shell so sphere peeks cleanly under rim)
    ctx.beginPath();
    ctx.moveTo(0, bellH * 0.20);
    ctx.lineTo(clapX, clapY);
    ctx.strokeStyle = '#945130';
    ctx.lineWidth = minSide * 0.007;
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(clapX, clapY, minSide * 0.024, 0, Math.PI * 2);
    const clapGrad = ctx.createLinearGradient(clapX - minSide * 0.02, clapY - minSide * 0.02, clapX + minSide * 0.02, clapY + minSide * 0.02);
    clapGrad.addColorStop(0, '#FFE4BE');
    clapGrad.addColorStop(1, '#B3633D');
    ctx.fillStyle = clapGrad;
    ctx.fill();

    // Bell outer body contour
    const topY = minSide * 0.014;
    const bodyBotY = rimY - minSide * 0.016;
    const bellGrad = ctx.createLinearGradient(-rimHalfW, topY, rimHalfW, bodyBotY);
    bellGrad.addColorStop(0, '#FFE4C2');
    bellGrad.addColorStop(0.32, '#F0B280');
    bellGrad.addColorStop(0.75, '#C97B4D');
    bellGrad.addColorStop(1, '#9E5531');

    ctx.beginPath();
    ctx.moveTo(-domeHalfW * 0.72, topY + minSide * 0.018);
    ctx.quadraticCurveTo(0, topY - minSide * 0.018, domeHalfW * 0.72, topY + minSide * 0.018);
    ctx.bezierCurveTo(
      domeHalfW * 1.15,
      bellH * 0.34,
      rimHalfW * 0.78,
      bellH * 0.72,
      rimHalfW * 0.94,
      bodyBotY
    );
    ctx.lineTo(-rimHalfW * 0.94, bodyBotY);
    ctx.bezierCurveTo(
      -rimHalfW * 0.78,
      bellH * 0.72,
      -domeHalfW * 1.15,
      bellH * 0.34,
      -domeHalfW * 0.72,
      topY + minSide * 0.018
    );
    ctx.closePath();
    ctx.fillStyle = bellGrad;
    ctx.fill();

    // Clean sleek 2D left specular highlight band inside bell
    ctx.save();
    ctx.clip();
    ctx.beginPath();
    ctx.moveTo(-domeHalfW * 0.38, topY + minSide * 0.030);
    ctx.bezierCurveTo(
      -domeHalfW * 0.58,
      bellH * 0.35,
      -rimHalfW * 0.50,
      bellH * 0.70,
      -rimHalfW * 0.62,
      bodyBotY - minSide * 0.012
    );
    ctx.strokeStyle = 'rgba(255, 245, 232, 0.42)';
    ctx.lineWidth = minSide * 0.012;
    ctx.stroke();
    ctx.restore();

    // Crisp Engraved Rim Collar Lip
    const lipH = minSide * 0.028;
    const lipGrad = ctx.createLinearGradient(-rimHalfW, bodyBotY, rimHalfW, bodyBotY);
    lipGrad.addColorStop(0, '#FFF0D6');
    lipGrad.addColorStop(0.5, '#E49D6A');
    lipGrad.addColorStop(1, '#A45A36');

    ctx.beginPath();
    ctx.roundRect(-rimHalfW, bodyBotY - minSide * 0.004, rimHalfW * 2, lipH, lipH * 0.48);
    ctx.fillStyle = lipGrad;
    ctx.fill();

    // Subtle crisp trim line above rim lip
    ctx.beginPath();
    ctx.moveTo(-rimHalfW * 0.85, bodyBotY - minSide * 0.014);
    ctx.lineTo(rimHalfW * 0.85, bodyBotY - minSide * 0.014);
    ctx.strokeStyle = '#FFE5C4';
    ctx.lineWidth = minSide * 0.0036;
    ctx.stroke();

    ctx.restore();
  }

  // 4. Outer Concentric Acoustic Soundwave Arcs (Strictly outside bells max swing radius > 0.35 * minSide)
  if (waveAlpha > 0.005) {
    const waveOriginY = pivotY + bellH * 0.72;
    for (let side = -1; side <= 1; side += 2) {
      const originX = cx + side * minSide * 0.04;
      for (let w = 0; w < 2; w++) {
        const u = (wavePhase + w * 0.5) % 1;
        const r = minSide * (0.340 + u * 0.075);
        const arcAlpha = waveAlpha * Math.sin(u * Math.PI) * 0.82;
        if (arcAlpha <= 0.01) continue;

        ctx.save();
        ctx.globalAlpha = arcAlpha;
        ctx.strokeStyle = w === 0 ? '#FFE8B8' : '#F4B886';
        ctx.lineWidth = minSide * (0.0055 * (1 - u * 0.35));

        const startAng = side > 0 ? (-15 * Math.PI) / 180 : (165 * Math.PI) / 180;
        const endAng = side > 0 ? (15 * Math.PI) / 180 : (195 * Math.PI) / 180;
        ctx.beginPath();
        ctx.arc(originX, waveOriginY, r, startAng, endAng);
        ctx.stroke();
        ctx.restore();
      }
    }
  }

  // 5. Flanking Champagne Chime Sparks (Strictly outside waves & bow, zero overlap)
  if (chimeAlpha > 0.005) {
    const chimes = [
      { x: cx - minSide * 0.42, y: cy - minSide * 0.16, sz: minSide * 0.015, sp: 0.6 },
      { x: cx - minSide * 0.51, y: cy + minSide * 0.11, sz: minSide * 0.012, sp: -0.7 },
      { x: cx + minSide * 0.42, y: cy - minSide * 0.16, sz: minSide * 0.015, sp: -0.6 },
      { x: cx + minSide * 0.51, y: cy + minSide * 0.11, sz: minSide * 0.012, sp: 0.7 },
    ];
    for (let i = 0; i < chimes.length; i++) {
      const ch = chimes[i];
      const pulse = 0.84 + 0.16 * Math.sin(loopT * Math.PI * 0.9 + i * 1.3);
      drawSpark(
        ch.x,
        ch.y,
        ch.sz * chimeAlpha * pulse,
        loopT * ch.sp + i,
        i % 2 === 0 ? '#FFE8B8' : '#F4B886',
        chimeAlpha * 0.9
      );
    }
  }

  // 6. Twin Symmetrical Rose-Gold Bells (Left tilts positive/left, Right tilts negative/right)
  drawBell(leftPivotX, pivotY, baseSpreadDeg + swingDeg, clapperDeg, bellScale, bellAlpha);
  drawBell(rightPivotX, pivotY, -(baseSpreadDeg + swingDeg), -clapperDeg, bellScale, bellAlpha);

  // 7. Upper Velvet Scarlet Ribbon Yoke, Flowing Upper-Outward Tails & Bow (Strictly above bells)
  const bowCy = pivotY - minSide * 0.068;

  // Flowing upward-outward ribbon tails (kept strictly above y = pivotY - 0.035 * minSide)
  if (ribbonReveal > 0.01) {
    const tailMaxLen = minSide * 0.175 * ribbonReveal;
    for (let side = -1; side <= 1; side += 2) {
      const startX = cx + side * minSide * 0.042;
      const startY = bowCy - minSide * 0.005;
      const segs = 20;

      ctx.save();
      ctx.beginPath();
      for (let s = 0; s <= segs; s++) {
        const u = s / segs;
        const px = startX + side * (u * tailMaxLen);
        const wave = Math.sin(u * Math.PI * 2.0 - ribbonFlutterPhase) * (minSide * 0.013) * Math.sin(u * Math.PI);
        const archUp = -Math.sin(u * Math.PI * 0.65) * (minSide * 0.032) - u * (minSide * 0.024);
        const py = startY + archUp + wave;
        if (s === 0) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
      }
      ctx.strokeStyle = '#C92030';
      ctx.lineWidth = minSide * 0.022 * Math.min(1, ribbonReveal * 1.4);
      ctx.globalAlpha = clamp01(ribbonReveal * 1.3);
      ctx.stroke();

      // Inner crisp satin highlight along tail center
      ctx.strokeStyle = '#FF5C6C';
      ctx.lineWidth = minSide * 0.0055 * Math.min(1, ribbonReveal * 1.4);
      ctx.stroke();
      ctx.restore();
    }
  }

  // Connecting Horizontal Gold Yoke Bar (Bridges top pivot rings cleanly)
  if (bellScale > 0.01) {
    const yokeW = pivotSepX * 2 * Math.min(1, bellScale * 1.15);
    ctx.save();
    ctx.globalAlpha = bellAlpha;
    ctx.beginPath();
    ctx.moveTo(cx - yokeW * 0.5, pivotY - minSide * 0.022);
    ctx.lineTo(cx + yokeW * 0.5, pivotY - minSide * 0.022);
    ctx.strokeStyle = '#F2B880';
    ctx.lineWidth = minSide * 0.011;
    ctx.stroke();
    ctx.restore();
  }

  // Symmetrical Bow Loops & Center Knot
  if (bowScale > 0.01) {
    ctx.save();
    ctx.translate(cx, bowCy);
    ctx.scale(bowScale, bowScale);

    const loopW = minSide * 0.088;
    const loopH = minSide * 0.048;

    for (let side = -1; side <= 1; side += 2) {
      // Back folded ribbon shadow
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.bezierCurveTo(
        side * loopW * 0.55,
        -loopH * 1.05,
        side * loopW * 1.12,
        -loopH * 0.62,
        side * loopW,
        loopH * 0.14
      );
      ctx.bezierCurveTo(
        side * loopW * 0.85,
        loopH * 0.58,
        side * loopW * 0.35,
        loopH * 0.36,
        0,
        minSide * 0.006
      );
      ctx.closePath();

      const bowGrad = ctx.createLinearGradient(0, -loopH, side * loopW, loopH * 0.5);
      bowGrad.addColorStop(0, '#FF5464');
      bowGrad.addColorStop(0.55, '#E63946');
      bowGrad.addColorStop(1, '#A61926');
      ctx.fillStyle = bowGrad;
      ctx.fill();

      // Inner folded crease highlight
      ctx.beginPath();
      ctx.moveTo(side * loopW * 0.20, -loopH * 0.08);
      ctx.quadraticCurveTo(side * loopW * 0.65, -loopH * 0.42, side * loopW * 0.80, -loopH * 0.02);
      ctx.strokeStyle = 'rgba(255, 224, 228, 0.42)';
      ctx.lineWidth = minSide * 0.0055;
      ctx.stroke();
    }

    // Center Bow Knot
    const knotSize = minSide * 0.036;
    ctx.beginPath();
    ctx.roundRect(-knotSize * 0.52, -knotSize * 0.45, knotSize * 1.04, knotSize * 0.92, knotSize * 0.32);
    const knotGrad = ctx.createLinearGradient(-knotSize * 0.5, -knotSize * 0.5, knotSize * 0.5, knotSize * 0.5);
    knotGrad.addColorStop(0, '#FF6876');
    knotGrad.addColorStop(1, '#B31C2A');
    ctx.fillStyle = knotGrad;
    ctx.fill();

    ctx.restore();
  }

  // Seamless Central Anchor Finial Seed (Always present at t=0 and t=20)
  if (seedAlpha > 0.01) {
    ctx.beginPath();
    ctx.arc(cx, bowCy, minSide * 0.0095, 0, Math.PI * 2);
    ctx.fillStyle = '#FFE5C4';
    ctx.fill();
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.min(sceneCount - 1, Math.floor(loopT / sceneDuration));
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const subP = (p, a, b) => clamp01((p - a) / (b - a));
  const easeInOutCubic = (x) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2);
  const easeOutCubic = (x) => 1 - Math.pow(1 - x, 3);
  const easeInCubic = (x) => x * x * x;

  ctx.save();
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  // 1. Clean Modern Dark Aesthetic Gradient Background (Zero glow effects)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, '#110807');
  bgGrad.addColorStop(0.5, '#22110E');
  bgGrad.addColorStop(1, '#0C0605');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Timeline Choreography Parameters
  let coasterScale = 1;
  let mugScale = 1;
  let mugAlpha = 1;
  let cocoaFill = 0.62;
  let cocoaAlpha = 1;
  let waveAmpFactor = 1;
  let candyProgress = 1;
  let marshProgress = 0;
  let steamIntensity = 0;
  let accentReveal = 0;

  if (currentScene === 0) {
    // Scene 1: Coaster & glass mug emergence, smooth internal cocoa rise, candy cane glide-in
    coasterScale = 0.25 + 0.75 * easeOutCubic(subP(sceneProgress, 0.0, 0.16));
    mugScale = easeOutCubic(subP(sceneProgress, 0.04, 0.22));
    mugAlpha = easeInOutCubic(subP(sceneProgress, 0.04, 0.18));

    const pourT = subP(sceneProgress, 0.20, 0.76);
    cocoaFill = 0.26 + 0.36 * easeInOutCubic(pourT);
    cocoaAlpha = easeOutCubic(subP(pourT, 0.0, 0.14));
    waveAmpFactor = easeOutCubic(subP(sceneProgress, 0.22, 0.38));

    candyProgress = easeOutCubic(subP(sceneProgress, 0.74, 0.98));
    marshProgress = 0;
    steamIntensity = 0;
    accentReveal = 0;
  } else if (currentScene === 1) {
    // Scene 2: Marshmallow buoyancy bobbing, 3 crisp S-curve steam lanes, geometric sparks
    coasterScale = 1;
    mugScale = 1;
    mugAlpha = 1;
    cocoaFill = 0.62;
    cocoaAlpha = 1;
    waveAmpFactor = 1;
    candyProgress = 1;

    marshProgress = easeOutCubic(subP(sceneProgress, 0.02, 0.26));
    steamIntensity = easeInOutCubic(subP(sceneProgress, 0.12, 0.36));
    accentReveal = easeInOutCubic(subP(sceneProgress, 0.14, 0.36));
  } else {
    // Scene 3: Graceful steam dissipation, candy cane exit, cocoa drain, clean reset
    steamIntensity = 1 - easeInOutCubic(subP(sceneProgress, 0.0, 0.34));
    accentReveal = 1 - easeInOutCubic(subP(sceneProgress, 0.08, 0.36));
    marshProgress = 1 - easeInCubic(subP(sceneProgress, 0.18, 0.42));
    candyProgress = 1 - easeInOutCubic(subP(sceneProgress, 0.26, 0.54));

    const drainT = subP(sceneProgress, 0.48, 0.80);
    cocoaFill = 0.26 + 0.36 * (1 - easeInOutCubic(drainT));
    cocoaAlpha = 1 - easeInCubic(subP(drainT, 0.82, 1.0));
    waveAmpFactor = 1 - easeInCubic(subP(sceneProgress, 0.60, 0.80));

    mugScale = 1 - easeInCubic(subP(sceneProgress, 0.78, 0.96));
    mugAlpha = 1 - easeInOutCubic(subP(sceneProgress, 0.78, 0.95));
    coasterScale = 1 - 0.75 * easeInOutCubic(subP(sceneProgress, 0.82, 1.0));
  }

  // 3. Layout Constants (Centered inclusive of handle & coaster)
  const mugW = minSide * 0.35;
  const mugH = minSide * 0.36;
  const wallStroke = minSide * 0.0085;
  const handleW = minSide * 0.098;
  const mugCx = cx - handleW * 0.42;
  const mugBottom = cy + minSide * 0.252;
  const mugTop = mugBottom - mugH;
  const innerW = mugW - wallStroke * 2.2;
  const innerLeft = mugCx - innerW * 0.5;
  const innerRight = mugCx + innerW * 0.5;
  const innerBottom = mugBottom - wallStroke * 1.1;
  const innerTop = mugTop + wallStroke * 0.8;
  const innerH = innerBottom - innerTop;
  const cornerR = minSide * 0.065;

  function drawMugInteriorPath(inset) {
    const l = mugCx - mugW * 0.5 + inset;
    const r = mugCx + mugW * 0.5 - inset;
    const tY = mugTop + inset * 0.4;
    const bY = mugBottom - inset;
    const rad = Math.max(4, cornerR - inset);
    const topRad = minSide * 0.012;

    ctx.beginPath();
    ctx.moveTo(l + topRad, tY);
    ctx.lineTo(r - topRad, tY);
    ctx.quadraticCurveTo(r, tY, r, tY + topRad);
    ctx.lineTo(r, bY - rad);
    ctx.quadraticCurveTo(r, bY, r - rad, bY);
    ctx.lineTo(l + rad, bY);
    ctx.quadraticCurveTo(l, bY, l, bY - rad);
    ctx.lineTo(l, tY + topRad);
    ctx.quadraticCurveTo(l, tY, l + topRad, tY);
    ctx.closePath();
  }

  // Helper: Crisp 4-point festive diamond spark
  function drawSpark(sx, sy, sz, rot, col, alpha) {
    if (sz <= 0.4 || alpha <= 0.01) return;
    ctx.save();
    ctx.translate(sx, sy);
    ctx.rotate(rot);
    ctx.globalAlpha = alpha;
    ctx.beginPath();
    const inner = sz * 0.30;
    for (let i = 0; i < 8; i++) {
      const a = (i * Math.PI) / 4;
      const r = i % 2 === 0 ? sz : inner;
      if (i === 0) ctx.moveTo(Math.cos(a) * r, Math.sin(a) * r);
      else ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r);
    }
    ctx.closePath();
    ctx.fillStyle = col;
    ctx.fill();
    ctx.restore();
  }

  // Helper: Precision Modern Flat Vector Candy Cane with clipped diagonal stripes
  function drawCandyCane(pivotX, pivotY, angle, liftY, alpha) {
    if (alpha <= 0.01) return;
    ctx.save();
    ctx.translate(pivotX, pivotY + liftY);
    ctx.rotate(angle);
    ctx.globalAlpha = alpha;

    const hw = minSide * 0.0135;
    const stemBot = mugH * 0.44;
    const stemTop = mugH * 0.25;
    const hookR = minSide * 0.036;
    const tipDrop = minSide * 0.022;

    const traceCaneContour = () => {
      ctx.beginPath();
      ctx.arc(0, stemBot, hw, 0, Math.PI, false);
      ctx.lineTo(-hw, -stemTop);
      ctx.arc(hookR, -stemTop, hookR + hw, Math.PI, 0, false);
      ctx.lineTo(hookR * 2 + hw, -stemTop + tipDrop);
      ctx.arc(hookR * 2, -stemTop + tipDrop, hw, 0, Math.PI, false);
      ctx.lineTo(hookR * 2 - hw, -stemTop);
      ctx.arc(hookR, -stemTop, hookR - hw, 0, Math.PI, true);
      ctx.lineTo(hw, stemBot);
      ctx.closePath();
    };

    ctx.save();
    traceCaneContour();
    ctx.clip();

    ctx.fillStyle = '#F7EFE6';
    ctx.fillRect(-hw * 2, -stemTop - hookR - hw * 2, hookR * 2 + hw * 4, stemBot + stemTop + hookR + hw * 4);

    ctx.save();
    ctx.rotate(-Math.PI / 4);
    const stripePitch = minSide * 0.044;
    for (let y = -minSide * 0.45; y < minSide * 0.45; y += stripePitch) {
      ctx.fillStyle = '#E63946';
      ctx.fillRect(-minSide * 0.35, y, minSide * 0.70, stripePitch * 0.34);
      ctx.fillStyle = '#2EC496';
      ctx.fillRect(-minSide * 0.35, y + stripePitch * 0.50, minSide * 0.70, stripePitch * 0.16);
    }
    ctx.restore();
    ctx.restore();

    traceCaneContour();
    ctx.strokeStyle = '#3B1915';
    ctx.lineWidth = minSide * 0.0045;
    ctx.stroke();

    ctx.restore();
  }

  // 4. Exterior Flanking Peppermint & Gold Geometric Sparks (Strictly clear of mug & handle)
  if (accentReveal > 0.005) {
    const sparks = [
      { x: cx - minSide * 0.36, y: cy - minSide * 0.14, r: minSide * 0.017, col: '#F5C96B', sp: 0.6 },
      { x: cx - minSide * 0.40, y: cy + minSide * 0.04, r: minSide * 0.012, col: '#2EC496', sp: -0.8 },
      { x: cx + minSide * 0.36, y: cy - minSide * 0.12, r: minSide * 0.016, col: '#2EC496', sp: -0.7 },
      { x: cx + minSide * 0.39, y: cy + minSide * 0.06, r: minSide * 0.013, col: '#E63946', sp: 0.7 },
    ];
    for (let i = 0; i < sparks.length; i++) {
      const sp = sparks[i];
      const pulse = 0.85 + 0.15 * Math.sin(loopT * Math.PI * 0.8 + i * 1.4);
      drawSpark(
        sp.x,
        sp.y,
        sp.r * accentReveal * pulse,
        loopT * sp.sp + i,
        sp.col,
        0.90 * accentReveal
      );
    }
  }

  // 5. Sleek Two-Tone Flat Vector Coaster (Seated cleanly under mug with crisp gap)
  if (coasterScale > 0.01) {
    const coasterW = mugW * 1.18 * coasterScale;
    const coasterH = minSide * 0.023;
    const coasterY = mugBottom + minSide * 0.010;

    ctx.save();
    ctx.beginPath();
    ctx.roundRect(mugCx - coasterW * 0.5, coasterY, coasterW, coasterH, coasterH * 0.45);
    ctx.fillStyle = '#F4ECE1';
    ctx.fill();

    ctx.beginPath();
    ctx.roundRect(
      mugCx - coasterW * 0.44,
      coasterY + coasterH * 0.55,
      coasterW * 0.88,
      coasterH * 0.45,
      coasterH * 0.25
    );
    ctx.fillStyle = '#2EC496';
    ctx.fill();
    ctx.restore();
  }

  // 6. Hero Mug Assembly (Scaled cleanly from mug bottom center)
  if (mugScale > 0.01 && mugAlpha > 0.01) {
    ctx.save();
    ctx.translate(mugCx, mugBottom);
    ctx.scale(mugScale, mugScale);
    ctx.translate(-mugCx, -mugBottom);
    ctx.globalAlpha = mugAlpha;

    // 6A. Handle on Right Side (Draws behind right wall stroke)
    const handleTopY = mugTop + mugH * 0.20;
    const handleBotY = mugTop + mugH * 0.72;
    const mugRightX = mugCx + mugW * 0.5;
    const handleOuterX = mugRightX + handleW;

    ctx.beginPath();
    ctx.moveTo(mugRightX, handleTopY);
    ctx.bezierCurveTo(
      handleOuterX,
      handleTopY - minSide * 0.005,
      handleOuterX,
      handleBotY + minSide * 0.005,
      mugRightX,
      handleBotY
    );
    ctx.strokeStyle = '#F4ECE1';
    ctx.lineWidth = minSide * 0.034;
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(mugRightX + minSide * 0.002, handleTopY);
    ctx.bezierCurveTo(
      handleOuterX - minSide * 0.006,
      handleTopY + minSide * 0.004,
      handleOuterX - minSide * 0.006,
      handleBotY - minSide * 0.004,
      mugRightX + minSide * 0.002,
      handleBotY
    );
    ctx.strokeStyle = '#180B09';
    ctx.lineWidth = minSide * 0.014;
    ctx.stroke();

    // 6B. Frosted Clear Glass Mug Backing
    drawMugInteriorPath(0);
    ctx.fillStyle = 'rgba(244, 236, 225, 0.08)';
    ctx.fill();

    // 6C. Candy Cane Hook Above Rim (Positioned cleanly inside right-mid rim clear of corner & steam)
    const caneX = mugCx + innerW * 0.16;
    const caneY = mugTop + mugH * 0.07;
    const caneLift = -(1 - candyProgress) * (mugH * 0.42);
    const caneAlpha = easeInOutCubic(subP(candyProgress, 0.0, 0.35));
    const caneAngle = (10 * Math.PI) / 180;

    if (candyProgress > 0.01 && caneAlpha > 0.01) {
      ctx.save();
      ctx.beginPath();
      ctx.rect(mugCx - mugW, 0, mugW * 2.5, mugTop + 1);
      ctx.clip();
      drawCandyCane(caneX, caneY, caneAngle, caneLift, caneAlpha);
      ctx.restore();
    }

    // 6D. Mug Interior Clipped Layer (Cocoa Liquid + Submerged Candy Cane + Marshmallows + Highlight)
    ctx.save();
    drawMugInteriorPath(wallStroke * 0.45);
    ctx.clip();

    if (candyProgress > 0.01 && caneAlpha > 0.01) {
      drawCandyCane(caneX, caneY, caneAngle, caneLift, caneAlpha * 0.96);
    }

    // Dynamic Cocoa Liquid Wave Calculation
    const baseSurfaceY = innerBottom - cocoaFill * innerH;
    const waveAmp1 = minSide * 0.009 * waveAmpFactor;
    const waveAmp2 = minSide * 0.004 * waveAmpFactor;
    const wavePhase = loopT * Math.PI * 1.15;

    const getCocoaWaveY = (xPos, phaseOff, ampScale) => {
      const nx = (xPos - mugCx) / (innerW * 0.5);
      return (
        baseSurfaceY +
        (Math.sin(nx * 2.8 + wavePhase + phaseOff) * waveAmp1 +
          Math.cos(nx * 4.5 - wavePhase * 1.15 + phaseOff) * waveAmp2) *
          ampScale
      );
    };

    const getCocoaWaveSlope = (xPos) => {
      const eps = 2;
      return Math.atan2(getCocoaWaveY(xPos + eps, 0, 1) - getCocoaWaveY(xPos - eps, 0, 1), eps * 2);
    };

    if (cocoaAlpha > 0.005) {
      ctx.save();
      ctx.globalAlpha = cocoaAlpha;
      const steps = 44;

      // Back dark cocoa wave layer
      ctx.beginPath();
      for (let s = 0; s <= steps; s++) {
        const px = innerLeft - 4 + (s / steps) * (innerW + 8);
        const py = getCocoaWaveY(px, 1.4, 0.8);
        if (s === 0) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
      }
      ctx.lineTo(innerRight + 8, mugBottom + 8);
      ctx.lineTo(innerLeft - 8, mugBottom + 8);
      ctx.closePath();
      ctx.fillStyle = '#5D2912';
      ctx.fill();

      // Marshmallows floating gently on wave surface (Left-shifted clear of Candy Cane)
      if (marshProgress > 0.01) {
        const marshes = [
          { x: mugCx - innerW * 0.28, w: innerW * 0.145, h: innerW * 0.11 },
          { x: mugCx - innerW * 0.07, w: innerW * 0.132, h: innerW * 0.10 },
        ];
        for (let m = 0; m < marshes.length; m++) {
          const mr = marshes[m];
          const mEnter = easeOutCubic(subP(marshProgress, m * 0.18, 0.72 + m * 0.25));
          if (mEnter <= 0.01) continue;
          const surfY = getCocoaWaveY(mr.x, 0, 1);
          const slope = getCocoaWaveSlope(mr.x) * 0.65;
          const dropY = -(1 - mEnter) * (mugH * 0.34);
          const my = surfY - mr.h * 0.34 + dropY;

          ctx.save();
          ctx.translate(mr.x, my);
          ctx.rotate(slope);
          ctx.scale(mEnter, mEnter);

          ctx.beginPath();
          ctx.roundRect(-mr.w * 0.5, -mr.h * 0.5, mr.w, mr.h, mr.h * 0.30);
          ctx.fillStyle = '#FFF9F2';
          ctx.fill();

          ctx.beginPath();
          ctx.roundRect(-mr.w * 0.45, 0, mr.w * 0.90, mr.h * 0.42, mr.h * 0.18);
          ctx.fillStyle = '#EBDDCE';
          ctx.fill();

          ctx.beginPath();
          ctx.roundRect(-mr.w * 0.34, -mr.h * 0.36, mr.w * 0.68, mr.h * 0.22, mr.h * 0.11);
          ctx.fillStyle = '#FFFFFF';
          ctx.fill();

          ctx.restore();
        }
      }

      // Primary Front Caramel Cocoa Layer
      const cocoaGrad = ctx.createLinearGradient(mugCx, baseSurfaceY - waveAmp1, mugCx, innerBottom);
      cocoaGrad.addColorStop(0, '#C7793E');
      cocoaGrad.addColorStop(0.28, '#9C4D20');
      cocoaGrad.addColorStop(1, '#6A2E11');

      ctx.beginPath();
      for (let s = 0; s <= steps; s++) {
        const px = innerLeft - 4 + (s / steps) * (innerW + 8);
        const py = getCocoaWaveY(px, 0, 1);
        if (s === 0) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
      }
      ctx.lineTo(innerRight + 8, mugBottom + 8);
      ctx.lineTo(innerLeft - 8, mugBottom + 8);
      ctx.closePath();
      ctx.fillStyle = cocoaGrad;
      ctx.fill();

      // Cream swirl meniscus ribbon across top wave
      ctx.beginPath();
      for (let s = 0; s <= steps; s++) {
        const px = innerLeft - 4 + (s / steps) * (innerW + 8);
        const py = getCocoaWaveY(px, 0, 1);
        if (s === 0) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
      }
      ctx.strokeStyle = '#F7DEC3';
      ctx.lineWidth = Math.max(2, minSide * 0.0044);
      ctx.stroke();

      ctx.restore();
    }

    // Lower Exterior Ceramic Cozy Band (Modern Scandinavian festive pattern)
    const bandTop = mugBottom - mugH * 0.30;
    ctx.fillStyle = '#2EC496';
    ctx.fillRect(mugCx - mugW * 0.55, bandTop, mugW * 1.1, mugH * 0.35);

    ctx.fillStyle = '#E63946';
    ctx.fillRect(mugCx - mugW * 0.55, bandTop, mugW * 1.1, mugH * 0.055);

    const diamondCount = 5;
    const diamondSpacing = innerW / (diamondCount + 0.4);
    const diamondY = bandTop + mugH * 0.165;
    const diamondR = mugH * 0.045;
    ctx.fillStyle = '#F4ECE1';
    for (let d = 0; d < diamondCount; d++) {
      const dx = mugCx + (d - (diamondCount - 1) * 0.5) * diamondSpacing;
      ctx.beginPath();
      ctx.moveTo(dx, diamondY - diamondR);
      ctx.lineTo(dx + diamondR * 0.85, diamondY);
      ctx.lineTo(dx, diamondY + diamondR);
      ctx.lineTo(dx - diamondR * 0.85, diamondY);
      ctx.closePath();
      ctx.fill();
    }

    // Sleek vertical glass highlight on far-left wall
    ctx.save();
    ctx.globalAlpha = 0.28;
    ctx.beginPath();
    ctx.roundRect(
      mugCx - innerW * 0.435,
      mugTop + mugH * 0.10,
      minSide * 0.014,
      mugH * 0.50,
      minSide * 0.007
    );
    ctx.fillStyle = '#FFFFFF';
    ctx.fill();
    ctx.restore();

    ctx.restore(); // End Mug Interior Clip

    // 6E. Crisp Outer Glass Mug Stroke
    drawMugInteriorPath(0);
    ctx.strokeStyle = '#F4ECE1';
    ctx.lineWidth = wallStroke;
    ctx.stroke();

    ctx.restore(); // End Hero Mug Group
  }

  // 7. Three Non-Overlapping S-Curve Warm Steam Ribbons (Left-shifted clear of Candy Cane hook)
  if (steamIntensity > 0.01) {
    const lanes = [
      { x: mugCx - innerW * 0.28, h: minSide * 0.142, phase: 0.0, w: minSide * 0.0066 },
      { x: mugCx - innerW * 0.12, h: minSide * 0.172, phase: 1.8, w: minSide * 0.0072 },
      { x: mugCx + innerW * 0.04, h: minSide * 0.135, phase: 3.4, w: minSide * 0.0062 },
    ];
    const steamBaseY = mugTop - minSide * 0.030;

    for (let i = 0; i < lanes.length; i++) {
      const ln = lanes[i];
      const swAmp = innerW * 0.022;
      const segs = 24;
      const waveMove = loopT * 2.4 + ln.phase;

      ctx.save();
      const stGrad = ctx.createLinearGradient(ln.x, steamBaseY, ln.x, steamBaseY - ln.h);
      stGrad.addColorStop(0, 'rgba(247, 222, 195, 0.86)');
      stGrad.addColorStop(0.65, 'rgba(247, 222, 195, 0.44)');
      stGrad.addColorStop(1, 'rgba(247, 222, 195, 0.0)');

      ctx.globalAlpha = steamIntensity;
      ctx.strokeStyle = stGrad;
      ctx.lineWidth = ln.w;

      ctx.beginPath();
      for (let s = 0; s <= segs; s++) {
        const u = s / segs;
        const py = steamBaseY - u * ln.h * steamIntensity;
        const px = ln.x + Math.sin(u * Math.PI * 2.2 - waveMove) * swAmp * Math.sin(u * Math.PI);
        if (s === 0) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
      }
      ctx.stroke();
      ctx.restore();
    }
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.min(sceneCount - 1, Math.floor(loopT / sceneDuration));
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const subP = (p, a, b) => clamp01((p - a) / (b - a));
  const easeInOutCubic = (x) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2);
  const easeOutCubic = (x) => 1 - Math.pow(1 - x, 3);
  const easeInCubic = (x) => x * x * x;
  const easeInOutSine = (x) => -(Math.cos(Math.PI * x) - 1) / 2;

  ctx.save();
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  // 1. Clean Modern Dark Aesthetic Gradient Background (Zero glow effects)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, '#050918');
  bgGrad.addColorStop(0.52, '#0B1633');
  bgGrad.addColorStop(1, '#060B1D');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Timeline Choreography Parameters
  let outlineBuild = 1;
  let glassFillAlpha = 1;
  let crownReveal = 1;
  let liquidFill = 0.40;
  let streamIn = 0;
  let streamOut = 0;
  let waveAmpFactor = 1;
  let gearReveal = 0;
  let gearAngle = 0;
  let crystalOrbitReveal = 0;
  let rayReveal = 0;
  let swingAngle = 0;

  if (currentScene === 0) {
    // Scene 1: Smooth trim-path frame formation + golden liquid pour
    outlineBuild = easeInOutCubic(subP(sceneProgress, 0.0, 0.24));
    crownReveal = easeOutCubic(subP(sceneProgress, 0.08, 0.28));
    glassFillAlpha = easeInOutCubic(subP(sceneProgress, 0.14, 0.30));

    const pourT = subP(sceneProgress, 0.24, 0.88);
    liquidFill = 0.40 * easeInOutCubic(pourT);
    streamIn = easeOutCubic(subP(sceneProgress, 0.22, 0.32));
    streamOut = easeInCubic(subP(sceneProgress, 0.80, 0.90));
    waveAmpFactor = easeOutCubic(subP(sceneProgress, 0.26, 0.42));
  } else if (currentScene === 1) {
    // Scene 2: Interlocking clockwork gears + orbital crystal diamonds + outer radial ticks
    outlineBuild = 1;
    crownReveal = 1;
    glassFillAlpha = 1;
    liquidFill = 0.40;
    waveAmpFactor = 1;

    gearReveal = easeOutCubic(subP(sceneProgress, 0.02, 0.26));
    const spinPhase = easeInOutSine(sceneProgress);
    gearAngle = spinPhase * (Math.PI * 1.5);

    crystalOrbitReveal = easeInOutCubic(subP(sceneProgress, 0.12, 0.34));
    rayReveal = easeInOutCubic(subP(sceneProgress, 0.16, 0.38));
  } else {
    // Scene 3: Dignified pendulum harmonic resonance + clean seamless reset
    outlineBuild = 1 - easeInOutCubic(subP(sceneProgress, 0.76, 0.98));
    crownReveal = 1 - easeInCubic(subP(sceneProgress, 0.70, 0.90));
    glassFillAlpha = 1 - easeInOutCubic(subP(sceneProgress, 0.68, 0.86));

    const swingWindow = subP(sceneProgress, 0.0, 0.56);
    const swingEnv = Math.sin(swingWindow * Math.PI);
    swingAngle = Math.sin(swingWindow * Math.PI * 2) * swingEnv * (4.0 * Math.PI / 180);

    gearReveal = 1 - easeInCubic(subP(sceneProgress, 0.48, 0.68));
    gearAngle = Math.PI * 1.5 + easeOutCubic(subP(sceneProgress, 0.0, 0.65)) * (Math.PI * 0.5);

    crystalOrbitReveal = 1 - easeInOutCubic(subP(sceneProgress, 0.44, 0.64));
    rayReveal = 1 - easeInOutCubic(subP(sceneProgress, 0.42, 0.62));

    const drainT = subP(sceneProgress, 0.58, 0.86);
    liquidFill = 0.40 * (1 - easeInOutCubic(drainT));
    waveAmpFactor = 1 - easeInCubic(subP(sceneProgress, 0.66, 0.86));
  }

  // 3. Geometric Layout Constants (16:9 4K/2K/FHD responsive via minSide)
  const R = minSide * 0.252;
  const strokeW = minSide * 0.0072;
  const innerR = R - strokeW * 0.55;
  const sphereY = cy + minSide * 0.055;
  const crownTopY = sphereY - R * 1.15;
  const ringCy = crownTopY - minSide * 0.026;
  const ringR = minSide * 0.026;
  const pivotY = ringCy - ringR;

  // Helper: Draw Precision Vector Gear with clean rounded trapezoidal teeth
  function drawGear(gx, gy, teeth, rp, ro, rr, angle, scale, fillCol, rimCol, hubCol) {
    if (scale <= 0.001) return;
    ctx.save();
    ctx.translate(gx, gy);
    ctx.scale(scale, scale);
    ctx.rotate(angle);

    const step = (Math.PI * 2) / teeth;
    const halfToothRoot = step * 0.22;
    const halfToothTip = step * 0.125;

    ctx.beginPath();
    for (let i = 0; i < teeth; i++) {
      const baseA = i * step;
      const a0 = baseA - step * 0.5;
      const a1 = baseA - halfToothRoot;
      const a2 = baseA - halfToothTip;
      const a3 = baseA + halfToothTip;
      const a4 = baseA + halfToothRoot;

      if (i === 0) {
        ctx.moveTo(Math.cos(a0) * rr, Math.sin(a0) * rr);
      } else {
        ctx.lineTo(Math.cos(a0) * rr, Math.sin(a0) * rr);
      }
      ctx.lineTo(Math.cos(a1) * rr, Math.sin(a1) * rr);
      ctx.lineTo(Math.cos(a2) * ro, Math.sin(a2) * ro);
      ctx.lineTo(Math.cos(a3) * ro, Math.sin(a3) * ro);
      ctx.lineTo(Math.cos(a4) * rr, Math.sin(a4) * rr);
    }
    ctx.closePath();

    ctx.fillStyle = fillCol;
    ctx.fill();

    // Inner recessed ring and spokes
    ctx.beginPath();
    ctx.arc(0, 0, rr * 0.72, 0, Math.PI * 2);
    ctx.fillStyle = '#0A132C';
    ctx.fill();

    ctx.lineWidth = Math.max(1.5, minSide * 0.003);
    ctx.strokeStyle = rimCol;
    ctx.stroke();

    const spokeCount = teeth >= 10 ? 4 : 3;
    ctx.strokeStyle = fillCol;
    ctx.lineWidth = rr * 0.20;
    for (let s = 0; s < spokeCount; s++) {
      const sa = (s * Math.PI * 2) / spokeCount;
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.lineTo(Math.cos(sa) * rr * 0.70, Math.sin(sa) * rr * 0.70);
      ctx.stroke();
    }

    // Precision central axle hub
    ctx.beginPath();
    ctx.arc(0, 0, rr * 0.30, 0, Math.PI * 2);
    ctx.fillStyle = hubCol;
    ctx.fill();

    ctx.beginPath();
    ctx.arc(0, 0, rr * 0.13, 0, Math.PI * 2);
    ctx.fillStyle = '#070E21';
    ctx.fill();

    ctx.restore();
  }

  // Helper: Draw Crisp 4-Point Geometric Crystal Star
  function drawCrystalStar(sx, sy, size, rot, color, alpha) {
    if (size <= 0.4 || alpha <= 0.01) return;
    ctx.save();
    ctx.translate(sx, sy);
    ctx.rotate(rot);
    ctx.globalAlpha = alpha;
    ctx.beginPath();
    const inner = size * 0.30;
    for (let i = 0; i < 8; i++) {
      const ang = (i * Math.PI) / 4;
      const rad = i % 2 === 0 ? size : inner;
      const px = Math.cos(ang) * rad;
      const py = Math.sin(ang) * rad;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
    ctx.restore();
  }

  // 4. Exterior Precision Radial Accent Ticks (Strictly outside sphere, clear of top crown)
  if (rayReveal > 0.005) {
    const tickCount = 12;
    const innerTickR = R + minSide * 0.050;
    const maxTickLen = minSide * 0.044;
    ctx.save();
    ctx.translate(cx, sphereY);
    for (let i = 0; i < tickCount; i++) {
      const isRight = i < 6;
      const idx = isRight ? i : i - 6;
      const baseDeg = isRight ? -42 + idx * 17.5 : 138 + idx * 17.5;
      const radAngle = (baseDeg * Math.PI) / 180;
      const stagger = clamp01((rayReveal - idx * 0.04) / 0.76);
      if (stagger <= 0.01) continue;

      const curLen = maxTickLen * stagger;
      const rStart = innerTickR + (1 - stagger) * (maxTickLen * 0.35);
      const rEnd = rStart + curLen;

      ctx.beginPath();
      ctx.moveTo(Math.cos(radAngle) * rStart, Math.sin(radAngle) * rStart);
      ctx.lineTo(Math.cos(radAngle) * rEnd, Math.sin(radAngle) * rEnd);
      ctx.strokeStyle = i % 2 === 0 ? '#F2C96B' : '#73E0F5';
      ctx.globalAlpha = 0.82 * stagger;
      ctx.lineWidth = minSide * 0.0040;
      ctx.stroke();
    }
    ctx.restore();
  }

  // 5. Suspended Hero Bauble Group (Rotates cleanly around top hanging pivot)
  ctx.save();
  ctx.translate(cx, pivotY);
  ctx.rotate(swingAngle);
  ctx.translate(-cx, -pivotY);

  // 5A. Interior Glass Sphere Content (Strictly clipped inside innerR)
  if (glassFillAlpha > 0.005 || liquidFill > 0.002) {
    ctx.save();
    ctx.beginPath();
    ctx.arc(cx, sphereY, innerR, 0, Math.PI * 2);
    ctx.clip();

    if (glassFillAlpha > 0.005) {
      ctx.save();
      ctx.globalAlpha = glassFillAlpha;
      const glassGrad = ctx.createLinearGradient(cx, sphereY - innerR, cx, sphereY + innerR);
      glassGrad.addColorStop(0, '#102048');
      glassGrad.addColorStop(0.55, '#0B1635');
      glassGrad.addColorStop(1, '#081028');
      ctx.fillStyle = glassGrad;
      ctx.fillRect(cx - innerR, sphereY - innerR, innerR * 2, innerR * 2);
      ctx.restore();
    }

    // Zone A: Pouring Golden Stream (Scene 1 only, strictly clear of gears)
    if (streamIn > 0.005 && streamOut < 0.995) {
      const streamTop = sphereY - innerR * 0.96 + (innerR * 1.96) * streamOut;
      const surfaceTargetY = sphereY + innerR - liquidFill * (2 * innerR);
      const streamBot = Math.min(
        surfaceTargetY + minSide * 0.01,
        sphereY - innerR * 0.96 + (surfaceTargetY - (sphereY - innerR * 0.96)) * streamIn
      );
      if (streamBot > streamTop + 2) {
        const halfWTop = minSide * 0.0092 * (1 - streamOut * 0.5);
        const halfWBot = minSide * 0.0058 * (1 - streamOut * 0.4);
        const streamGrad = ctx.createLinearGradient(cx, streamTop, cx, streamBot);
        streamGrad.addColorStop(0, '#FCE38A');
        streamGrad.addColorStop(1, '#E09B2D');
        ctx.fillStyle = streamGrad;
        ctx.beginPath();
        ctx.moveTo(cx - halfWTop, streamTop);
        ctx.lineTo(cx + halfWTop, streamTop);
        ctx.lineTo(cx + halfWBot, streamBot);
        ctx.lineTo(cx - halfWBot, streamBot);
        ctx.closePath();
        ctx.fill();
      }
    }

    // Zone B: Precision Interlocking Clockwork Gears (Strictly in upper-mid interior above liquid)
    if (gearReveal > 0.005) {
      const rp1 = innerR * 0.20;
      const ro1 = innerR * 0.23;
      const rr1 = innerR * 0.17;
      const g1x = cx - innerR * 0.02;
      const g1y = sphereY - innerR * 0.28;

      const alpha2 = (-22 * Math.PI) / 180;
      const rp2 = rp1 * (9 / 12);
      const ro2 = rp2 + innerR * 0.028;
      const rr2 = rp2 - innerR * 0.028;
      const d12 = rp1 + rp2;
      const g2x = g1x + Math.cos(alpha2) * d12;
      const g2y = g1y + Math.sin(alpha2) * d12;
      const theta2 = alpha2 + Math.PI - Math.PI / 9 + (12 / 9) * (alpha2 - gearAngle);

      const alpha3 = (158 * Math.PI) / 180;
      const rp3 = rp1 * (8 / 12);
      const ro3 = rp3 + innerR * 0.026;
      const rr3 = rp3 - innerR * 0.026;
      const d13 = rp1 + rp3;
      const g3x = g1x + Math.cos(alpha3) * d13;
      const g3y = g1y + Math.sin(alpha3) * d13;
      const theta3 = alpha3 + Math.PI - Math.PI / 8 + (12 / 8) * (alpha3 - gearAngle);

      const s1 = easeOutCubic(subP(gearReveal, 0.0, 0.55));
      const s2 = easeOutCubic(subP(gearReveal, 0.20, 0.78));
      const s3 = easeOutCubic(subP(gearReveal, 0.36, 1.0));

      drawGear(g2x, g2y, 9, rp2, ro2, rr2, theta2, s2, '#D99330', '#FFE08A', '#F6C65B');
      drawGear(g3x, g3y, 8, rp3, ro3, rr3, theta3, s3, '#4EC7E8', '#B8F3FF', '#79DEF7');
      drawGear(g1x, g1y, 12, rp1, ro1, rr1, gearAngle, s1, '#F5C453', '#FFF0B3', '#FFE082');
    }

    // Zone C: Upper Orbital Crystal Diamonds (Clear upper arc r = 0.77 * innerR)
    if (crystalOrbitReveal > 0.005) {
      const orbitR = innerR * 0.77;
      const starCount = 5;
      for (let i = 0; i < starCount; i++) {
        const baseSpan = -108 + i * 21;
        const travel = (loopT * 6.5) % 90;
        let deg = baseSpan + travel;
        if (deg > -18) deg -= 90;
        const edgeFade = subP(deg, -108, -94) * (1 - subP(deg, -32, -18));
        const rad = (deg * Math.PI) / 180;
        const sx = cx + Math.cos(rad) * orbitR;
        const sy = sphereY + Math.sin(rad) * orbitR;
        const starSz = innerR * (i % 2 === 0 ? 0.046 : 0.035) * crystalOrbitReveal;
        drawCrystalStar(
          sx,
          sy,
          starSz,
          loopT * 0.8 + i * 0.7,
          i % 2 === 0 ? '#E8FAFF' : '#FFE89E',
          0.92 * crystalOrbitReveal * edgeFade
        );
      }
    }

    // Zone A: Flowing Champagne-Gold Liquid Basin (Strictly below gears)
    if (liquidFill > 0.002) {
      const baseSurfaceY = sphereY + innerR - liquidFill * (2 * innerR);
      const tiltSlope = Math.tan(-swingAngle) * 0.85;
      const amp1 = innerR * 0.025 * waveAmpFactor;
      const amp2 = innerR * 0.011 * waveAmpFactor;
      const phase = loopT * Math.PI * 1.2;

      const waveY = (dx, phaseShift, ampMul) => {
        const nx = dx / innerR;
        return (
          baseSurfaceY +
          dx * tiltSlope +
          (Math.sin(nx * 3.1 + phase + phaseShift) * amp1 +
            Math.cos(nx * 5.2 - phase * 1.2 + phaseShift) * amp2) *
            ampMul
        );
      };

      const steps = 48;
      // Back wave layer
      ctx.beginPath();
      for (let s = 0; s <= steps; s++) {
        const dx = -innerR + (s / steps) * (2 * innerR);
        const wy = waveY(dx, 1.5, 0.85);
        if (s === 0) ctx.moveTo(cx + dx, wy);
        else ctx.lineTo(cx + dx, wy);
      }
      ctx.lineTo(cx + innerR, sphereY + innerR + 4);
      ctx.lineTo(cx - innerR, sphereY + innerR + 4);
      ctx.closePath();
      ctx.fillStyle = '#B97318';
      ctx.fill();

      // Front primary golden liquid layer
      const liqGrad = ctx.createLinearGradient(cx, baseSurfaceY - amp1, cx, sphereY + innerR);
      liqGrad.addColorStop(0, '#FFE38A');
      liqGrad.addColorStop(0.35, '#EBB038');
      liqGrad.addColorStop(1, '#B86E14');

      ctx.beginPath();
      for (let s = 0; s <= steps; s++) {
        const dx = -innerR + (s / steps) * (2 * innerR);
        const wy = waveY(dx, 0, 1.0);
        if (s === 0) ctx.moveTo(cx + dx, wy);
        else ctx.lineTo(cx + dx, wy);
      }
      ctx.lineTo(cx + innerR, sphereY + innerR + 4);
      ctx.lineTo(cx - innerR, sphereY + innerR + 4);
      ctx.closePath();
      ctx.fillStyle = liqGrad;
      ctx.fill();

      // Crisp specular meniscus top stroke
      ctx.beginPath();
      for (let s = 0; s <= steps; s++) {
        const dx = -innerR + (s / steps) * (2 * innerR);
        const wy = waveY(dx, 0, 1.0);
        if (s === 0) ctx.moveTo(cx + dx, wy);
        else ctx.lineTo(cx + dx, wy);
      }
      ctx.strokeStyle = '#FFF5C8';
      ctx.lineWidth = Math.max(1.5, minSide * 0.003);
      ctx.stroke();

      // Two clean rising golden droplets (stay strictly between surface and y >= sphereY + 0.07 * innerR)
      const dropActive =
        currentScene === 0
          ? subP(sceneProgress, 0.55, 0.90)
          : currentScene === 1
          ? 1
          : 1 - subP(sceneProgress, 0.40, 0.65);

      if (dropActive > 0.01 && liquidFill > 0.25) {
        const drops = [
          { xOff: -0.34 * innerR, period: 3.333, shift: 0.0, r: 0.023 * innerR },
          { xOff: 0.36 * innerR, period: 3.333, shift: 1.666, r: 0.019 * innerR },
        ];
        for (let d = 0; d < drops.length; d++) {
          const dp = drops[d];
          const u = ((loopT + dp.shift) % dp.period) / dp.period;
          const arc = Math.sin(u * Math.PI);
          if (arc > 0.05) {
            const surfY = waveY(dp.xOff, 0, 1.0);
            const maxRise = Math.min(innerR * 0.11, surfY - (sphereY + innerR * 0.07));
            if (maxRise > 2) {
              const dy = surfY - arc * maxRise;
              const dx = cx + dp.xOff;
              ctx.beginPath();
              ctx.arc(dx, dy, dp.r * dropActive * (0.6 + 0.4 * arc), 0, Math.PI * 2);
              ctx.fillStyle = '#FFE89E';
              ctx.fill();
            }
          }
        }
      }
    }

    // Sleek Inner Glass Specular Highlight Crescent
    if (glassFillAlpha > 0.01) {
      ctx.save();
      ctx.globalAlpha = 0.24 * glassFillAlpha;
      ctx.beginPath();
      ctx.arc(cx, sphereY, innerR * 0.875, (-152 * Math.PI) / 180, (-118 * Math.PI) / 180);
      ctx.strokeStyle = '#FFFFFF';
      ctx.lineWidth = innerR * 0.042;
      ctx.stroke();

      ctx.beginPath();
      ctx.arc(cx, sphereY, innerR * 0.875, (-163 * Math.PI) / 180, (-158 * Math.PI) / 180);
      ctx.stroke();
      ctx.restore();
    }

    ctx.restore();
  }

  // 5B. Outer Crystal Sphere Rim (Clean symmetrical trim-path reveal without stub artifact)
  if (outlineBuild > 0.015) {
    const rimAlpha = subP(outlineBuild, 0.015, 0.10);
    const halfArc = Math.PI * outlineBuild;
    const rimGrad = ctx.createLinearGradient(cx - R, sphereY - R, cx + R, sphereY + R);
    rimGrad.addColorStop(0, '#FFF1B8');
    rimGrad.addColorStop(0.45, '#E8B852');
    rimGrad.addColorStop(1, '#9E6E1E');

    ctx.save();
    ctx.globalAlpha = rimAlpha;
    ctx.strokeStyle = rimGrad;
    ctx.lineWidth = strokeW;

    ctx.beginPath();
    ctx.arc(cx, sphereY, R, -Math.PI * 0.5, -Math.PI * 0.5 + halfArc, false);
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(cx, sphereY, R, -Math.PI * 0.5, -Math.PI * 0.5 - halfArc, true);
    ctx.stroke();
    ctx.restore();
  }

  // 5C. Fluted Gold Crown Cap & Hanging Ring
  if (crownReveal > 0.008) {
    ctx.save();
    ctx.globalAlpha = crownReveal;
    const capW = R * 0.36;
    const capBottom = sphereY - R * 0.945;
    const capTop = crownTopY;
    const capH = capBottom - capTop;

    ctx.beginPath();
    ctx.arc(cx, ringCy, ringR, 0, Math.PI * 2);
    ctx.strokeStyle = '#F5CF6B';
    ctx.lineWidth = strokeW * 0.78;
    ctx.stroke();

    const capGrad = ctx.createLinearGradient(cx - capW * 0.5, capTop, cx + capW * 0.5, capTop);
    capGrad.addColorStop(0, '#B58126');
    capGrad.addColorStop(0.35, '#F8DC88');
    capGrad.addColorStop(0.7, '#E0A83B');
    capGrad.addColorStop(1, '#9E6E1B');

    ctx.beginPath();
    ctx.roundRect(cx - capW * 0.5, capTop, capW, capH, capH * 0.22);
    ctx.fillStyle = capGrad;
    ctx.fill();
    ctx.lineWidth = strokeW * 0.62;
    ctx.strokeStyle = '#FFF2C2';
    ctx.stroke();

    ctx.strokeStyle = '#916114';
    ctx.lineWidth = strokeW * 0.38;
    for (let f = -1; f <= 1; f++) {
      const fx = cx + f * capW * 0.24;
      ctx.beginPath();
      ctx.moveTo(fx, capTop + capH * 0.22);
      ctx.lineTo(fx, capBottom - capH * 0.22);
      ctx.stroke();
    }
    ctx.restore();
  }

  // Top Anchor Finial Pin (Always present at t=0 and t=20 for seamless anchor)
  ctx.beginPath();
  ctx.arc(cx, pivotY, minSide * 0.0095, 0, Math.PI * 2);
  ctx.fillStyle = '#FFE599';
  ctx.fill();

  ctx.restore(); // End pendulum pivot group
  ctx.restore();
}
